INSERT INTO _su_script (script_id, content_id, sequence_num, script_content) VALUES
(361, 7, 1, '시청역 지하 2층, 유실물센터.'),
(362, 7, 2, '정해수의 5년치 아침은 대체로 비슷했다.'),
(363, 7, 3, '우산 열두 개, 이어폰 세 개, 주인 없는 백팩 하나.'),
(364, 7, 4, '수요일만 빼고.'),
(365, 7, 5, '수요일 오후 네 시 반이면 4호선 승무원이 같은 걸 들고 내려왔다.'),
(366, 7, 6, '스테인리스 2단 도시락통. 남색 보온 커버.'),
(367, 7, 7, '매번 비어 있었는데.'),
(368, 7, 8, '씻고 물기까지 닦아서 뚜껑을 비스듬히 얹어둔 상태였다.'),
(369, 7, 9, '버릴 거면 그냥 버리면 될 걸.'),
(370, 7, 10, '둘째 주부터 해수는 대장에 따로 표시를 남기기 시작했다.'),
(371, 7, 11, '뚜껑 안쪽, 유성펜으로 눌러 쓴 네 자리.'),
(372, 7, 12, '7213.'),
(373, 7, 13, '다음 주엔 7229. 그다음엔 7240.'),
(374, 7, 14, '날짜도 아니고 물품보관함 번호도 아니고.'),
(375, 7, 15, '간격도 제멋대로.'),
(376, 7, 16, '확실한 건 하나뿐이었는데.'),
(377, 7, 17, '발견 위치가 항상 같았다는 것. 6호차 4번 좌석 아래.'),
(378, 7, 18, '승무원은 매주 달랐다.'),
(379, 7, 19, '"놓고 내리는 사람 본 적 있어요?"'),
(380, 7, 20, '돌아오는 대답은 늘 고개 젓기.'),
(381, 7, 21, '편성 번호를 대조해봤다.'),
(382, 7, 22, '매주 다른 열차, 다른 시간대.'),
(383, 7, 23, '누군가 일부러 바꿔 타고 있다는 뜻인 셈이었다.'),
(384, 7, 24, '그런데 좌석만은 고집스럽게 6호차 4번.'),
(385, 7, 25, '네 번째 통에는 마른 쌀이 네 톨 들어 있었다.'),
(386, 7, 26, '다섯 번째 통엔 다섯 톨.'),
(387, 7, 27, '세고 있었다, 누군가.'),
(388, 7, 28, '여덟 번째 통을 받은 날, 해수는 숫자들을 노트에 나란히 옮겨 적었다.'),
(389, 7, 29, '7213, 7229, 7240, 7256, 7261, 7274, 7288, 7290.'),
(390, 7, 30, '어디서 많이 본 형식.'),
(391, 7, 31, '손끝이 먼저 알아챘다. 유실물 접수번호였다.'),
(392, 7, 32, '매일 자기 손으로 찍어내는 바로 그 번호.'),
(393, 7, 33, '조회창에 하나씩 넣어봤다.'),
(394, 7, 34, '여덟 건 전부 같은 날짜. 3년 전 5월 11일.'),
(395, 7, 35, '검정 장우산, 도수 높은 안경, 작업화 한 켤레, 낡은 지갑, 보온병, 무전기 배터리, 사원증, 손목시계.'),
(396, 7, 36, '소유자 이름도 하나였다. 장태섭, 58세.'),
(397, 7, 37, '접수자 칸에 찍힌 이름은 정해수.'),
(398, 7, 38, '3년 전이면 입사 3개월차.'),
(399, 7, 39, '비가 종일 내리던 날이 떠올랐다.'),
(400, 7, 40, '선로 보수 작업 중에 사람이 사라졌다고, 그 사람 물건이 한꺼번에 내려왔다고.'),
(401, 7, 41, '실종 신고는 접수됐고 결론은 나오지 않았다.'),
(402, 7, 42, '규정대로면 3년 지난 미수령품은 폐기다.'),
(403, 7, 43, '그런데 창고 맨 안쪽 선반에 상자가 그대로 있었다.'),
(404, 7, 44, '폐기 목록에서 매년 그 여덟 건만 빠져 있었는데, 뺀 사람이 누구인지는 알 것 같았다.'),
(405, 7, 45, '다음 수요일, 해수는 4호선 6호차에 서 있었다.'),
(406, 7, 46, '세 정거장을 지나도록 아무도 오지 않더니.'),
(407, 7, 47, '사당역에서 여자가 탔다. 삼십 대, 남색 보온 커버.'),
(408, 7, 48, '좌석 밑으로 통을 밀어 넣고 손잡이를 잡는 손.'),
(409, 7, 49, '"7213번, 검정 장우산이요."'),
(410, 7, 50, '여자가 천천히 고개를 들었다.'),
(411, 7, 51, '"...안 버리셨어요?"'),
(412, 7, 52, '"매년 폐기 목록에서 빼뒀어요. 왜 그랬는지는 저도 몰랐고요."'),
(413, 7, 53, '장윤희라고 했다.'),
(414, 7, 54, '아버지와 마지막으로 통화한 자리가 여기라고, 6호차 4번이라고.'),
(415, 7, 55, '"밥은 먹었냐고 물으셨는데. 제가 대답을 안 했어요."'),
(416, 7, 56, '그래서 매주 밥을 지어 담고, 여기 두고 내린다는 것이었다.'),
(417, 7, 57, '왜 도로 가져가지 않았냐고 물었다.'),
(418, 7, 58, '"유실물로 접수되면, 아버지 물건이랑 같은 창고로 가잖아요."'),
(419, 7, 59, '숫자를 적은 이유도 그거였다. 언젠가 누가 조회해보길 바라서.'),
(420, 7, 60, '여덟 주 동안 그녀가 기다린 건 도시락통이 아니었던 셈이다.'),
(421, 7, 61, '직원 한 명.'),
(422, 7, 62, '다음 날 해수는 창고 맨 안쪽 상자를 꺼내 접수대 위에 올렸다.'),
(423, 7, 63, '우산 손잡이 안쪽에 볼펜으로 눌러쓴 이름 세 글자.'),
(424, 7, 64, '인수증에 서명하던 손이 한참 멈춰 있었다.'),
(425, 7, 65, '그 주 수요일 오후 네 시 반.'),
(426, 7, 66, '4호선에서는 아무것도 내려오지 않았다.');
INSERT INTO _su_script (script_id, content_id, sequence_num, script_content) VALUES
(427, 8, 1, '나 작년부터 동네 클라이밍장 다녔거든.'),
(428, 8, 2, '운동 진짜 싫어하는데 회사 건물 3층에 새로 생겨서 그냥 홧김에 등록해버림.'),
(429, 8, 3, '화요일 목요일 저녁 8시, 그게 내 루틴이었는데 갈 때마다 항상 있는 사람이 하나 있는 거임.'),
(430, 8, 4, '검은 반팔에 왼쪽 손목만 테이핑하고 있는 남자였어.'),
(431, 8, 5, '말은 한 번도 안 걸더라.'),
(432, 8, 6, '나는 키가 158이라 초급 문제도 손 안 닿는 게 많았음.'),
(433, 8, 7, '특히 4번 벽 초록색 테이프 문제가 진짜 안 풀렸거든.'),
(434, 8, 8, '세 번째 홀드에서 다음 걸 잡으려면 살짝 뛰어야 되는데 그게 무서워서 계속 내려왔음.'),
(435, 8, 9, '근데 언제부턴가 내가 그 문제 붙을 때마다 그 사람이 매트 옆에 서 있는 거야.'),
(436, 8, 10, '처음엔 자기 순서 기다리는 줄 알았지.'),
(437, 8, 11, '근데 내가 떨어지면 바로 다른 벽으로 가버림ㅋㅋ'),
(438, 8, 12, '기다린 게 아니라 스팟 봐주고 있었던 거임.'),
(439, 8, 13, '어느 날은 내가 초크를 안 챙겨왔는데 옆에 초크백이 슬쩍 밀려와 있더라고.'),
(440, 8, 14, '고맙다고 했더니 "저 손에 땀 많아서 두 개 들고 다녀요" 이러는 거임.'),
(441, 8, 15, '초크백 두 개 들고 다니는 사람이 세상에 어디 있냐고.'),
(442, 8, 16, '그러다 내가 발목을 접질려서 못 나가게 됐음.'),
(443, 8, 17, '회사 일까지 겹쳐서 한 달 가까이 쉰 거지 뭐.'),
(444, 8, 18, '오랜만에 갔더니 벽이 통째로 바뀌어 있더라.'),
(445, 8, 19, '거기 원래 4주마다 홀드 다 뜯고 새로 세팅하잖음.'),
(446, 8, 20, '근데 4번 벽 초록색 문제만 그대로 남아 있는 거임.'),
(447, 8, 21, '옆 문제들은 다 새 색깔인데 그 하나만 테이프가 누렇게 뜬 채로 붙어 있었음.'),
(448, 8, 22, '사장님한테 이거 왜 안 뜯었냐고 물어봤거든.'),
(449, 8, 23, '"누가 계속 남겨달라고 해서요" 이러는 거임.'),
(450, 8, 24, '누구냐고 캐물었는데 그냥 웃고 말 안 해주더라.'),
(451, 8, 25, '그 주 목요일에 그 사람이 왔음.'),
(452, 8, 26, '나 보자마자 "발목 괜찮아요?" 이러는데, 나 발목 다친 거 아무한테도 말한 적 없거든.'),
(453, 8, 27, '마지막에 왔던 날 내가 절뚝거리면서 신발 갈아신는 거 봤다고 하더라고.'),
(454, 8, 28, '아 이거 큰일났다 싶었음.'),
(455, 8, 29, '그날 초록색 문제 다시 붙었는데 그 구간에서 또 손이 안 나가는 거야.'),
(456, 8, 30, '밑에서 "오른발을 왼쪽으로 한 칸만 옮기면 안 뛰어도 돼요" 이러는 거임.'),
(457, 8, 31, '진짜 그렇게 하니까 손이 그냥 닿았음.'),
(458, 8, 32, '한 달 동안 그 문제 발 순서를 혼자 다 계산해놨던 거지 뭐.'),
(459, 8, 33, '완등하고 내려왔더니 손 들고 서 있길래 나도 모르게 하이파이브 해버림.'),
(460, 8, 34, '근데 손에 땀 하나도 없더라ㅋㅋ 땀 많다는 사람이.'),
(461, 8, 35, '이제 문제 뜯어도 되겠다고 했음.'),
(462, 8, 36, '그랬더니 "다음 거 하나 더 부탁해놨어요" 이러더라.'),
(463, 8, 37, '뭘 부탁했냐니까 "이번엔 안 뛰어도 되는 걸로" 이러는 거임.'),
(464, 8, 38, '문제는 내가 아직 이 사람 이름도 모름.'),
(465, 8, 39, '완등 인증 게시판에 적는 닉네임이 ''손땀''인 거, 그거 하나만 알아냈거든.'),
(466, 8, 40, '어제 회원권 연장하러 갔는데 나도 모르게 화목 8시 시간표만 붙잡고 보고 있었어.'),
(467, 8, 41, '이거 내가 먼저 물어봐도 되는 거 맞냐고.'),
(468, 8, 42, '근데 그냥 초보 다치는 거 못 보는 착한 사람이면 나 거기 다시는 못 갈 것 같은데.'),
(469, 8, 43, '아직도 모르겠음.');
INSERT INTO _su_script (script_id, content_id, sequence_num, script_content) VALUES
(470, 9, 1, '하윤은 김밥이 지겨웠다.'),
(471, 9, 2, '3년째였으니까.'),
(472, 9, 3, '중3 겨울부터 고3 가을까지, 엄마는 하루도 빠짐없이 새벽에 김밥을 쌌다.'),
(473, 9, 4, '참기름 냄새로 잠이 깨는 아침.'),
(474, 9, 5, '"다른 거 좀 싸주면 안 돼?"'),
(475, 9, 6, '엄마는 대답 대신 웃기만 했는데.'),
(476, 9, 7, '"김밥이 제일 안 상해."'),
(477, 9, 8, '그 말만 3년.'),
(478, 9, 9, '그런데 9월쯤부터 맛이 조금씩 어긋나기 시작했다.'),
(479, 9, 10, '처음엔 단무지가 없었다.'),
(480, 9, 11, '다음 날엔 단무지가 두 줄씩 들어가 있었고.'),
(481, 9, 12, '그 주 목요일엔 밥이 너무 짜서 한 입 먹고 물을 세 번 마셨다.'),
(482, 9, 13, '짜증이 확 올라왔다.'),
(483, 9, 14, '쉬는 시간에 전화를 걸었다.'),
(484, 9, 15, '"엄마, 오늘 김밥 왜 이래."'),
(485, 9, 16, '"응? 이상해? 미안해, 다시 쌀게."'),
(486, 9, 17, '다시 쌀게라니.'),
(487, 9, 18, '점심시간이 끝나가는 중이었는데.'),
(488, 9, 19, '하윤은 그냥 끊었다.'),
(489, 9, 20, '10월 둘째 주 화요일.'),
(490, 9, 21, '야자가 있는 날인데 교문 앞에 엄마가 서 있었다.'),
(491, 9, 22, '장바구니를 든 채로.'),
(492, 9, 23, '"너 오늘 일찍 끝난다며."'),
(493, 9, 24, '그런 말을 한 적이 없었다.'),
(494, 9, 25, '"엄마, 오늘 화요일이야."'),
(495, 9, 26, '엄마가 잠깐 멈칫하더니 웃었다.'),
(496, 9, 27, '"아, 맞다. 엄마가 요일을 헷갈렸네."'),
(497, 9, 28, '그 웃음이 이상하게 오래 남았다.'),
(498, 9, 29, '며칠 뒤, 도시락 가방이 유난히 무거웠다.'),
(499, 9, 30, '열어보니 김밥이 여섯 줄.'),
(500, 9, 31, '평소엔 두 줄이었다.'),
(501, 9, 32, '친구들이 좋다고 달려들어서 순식간에 다 없어졌는데.'),
(502, 9, 33, '하윤만 웃지 못했다.'),
(503, 9, 34, '그날 밤, 물을 꺼내려고 부엌에 갔다가 엄마 앞치마가 의자에 걸려 있는 걸 봤다.'),
(504, 9, 35, '주머니가 불룩했다.'),
(505, 9, 36, '손바닥만 한 수첩.'),
(506, 9, 37, '펼쳐 보고 손이 멈췄다.'),
(507, 9, 38, '"하윤이 김밥 두 줄. 참기름 조금. 단무지 꼭."'),
(508, 9, 39, '다음 장에도 같은 문장.'),
(509, 9, 40, '그다음 장에도.'),
(510, 9, 41, '날짜만 바뀐 채로 스무 장 넘게 똑같은 글씨가 이어졌다.'),
(511, 9, 42, '뒤로 갈수록 글씨가 커지고 줄이 삐뚤어져 있었다.'),
(512, 9, 43, '맨 마지막 장 사이에 종이 한 장이 끼워져 있었는데.'),
(513, 9, 44, '대학병원 신경과 진료 카드.'),
(514, 9, 45, '석 달 전 날짜.'),
(515, 9, 46, '다음 예약 칸은 비어 있었다.'),
(516, 9, 47, '거짓말.'),
(517, 9, 48, '하윤은 수첩을 원래대로 접어서 주머니에 다시 넣었다.'),
(518, 9, 49, '그리고 방에 들어가 불을 끄고 한참을 누워 있었다.'),
(519, 9, 50, '다음 날 새벽 다섯 시 사십 분, 부엌에 불이 켜졌다.'),
(520, 9, 51, '하윤이 문을 열고 나갔다.'),
(521, 9, 52, '엄마가 김발 앞에서 놀란 얼굴로 돌아봤다.'),
(522, 9, 53, '"왜 벌써 일어났어."'),
(523, 9, 54, '"나도 배울래."'),
(524, 9, 55, '"너 김밥 싫어하잖아."'),
(525, 9, 56, '"아니."'),
(526, 9, 57, '"좋아해."'),
(527, 9, 58, '엄마가 잠깐 하윤을 보더니, 단무지 접시를 옆으로 밀어줬다.'),
(528, 9, 59, '손끝이 조금 떨렸다.'),
(529, 9, 60, '하윤은 수첩 얘기를 꺼내지 않았다.'),
(530, 9, 61, '대신 학교 앞 문구점에서 똑같은 수첩을 하나 샀다.'),
(531, 9, 62, '첫 장에 이렇게 적었다.'),
(532, 9, 63, '"엄마 김밥. 참기름 조금. 단무지 꼭."'),
(533, 9, 64, '이건 자기가 기억하기로 했다.');
INSERT INTO _su_quiz (content_id, break_no, difficulty, script_id, quiz_type) VALUES
(7, 1, 1, 373, 'multiple_choice'),
