INSERT INTO _su_content (content_id, difficulty, script_id, lang_code, question, options, correct_answer, explanation, hint, acceptable_answers) VALUES
(7, 1, 373, 'EN', '매주 수요일마다 깨끗이 씻긴 빈 도시락통이 유실물로 내려오는 상황. 이런 ''수상한, 의심스러운'' 느낌을 나타내는 영어 단어는?', '["serious","sensitive","suspicious","sincere"]', 'suspicious', '''suspicious''는 뭔가 수상하고 의심스러울 때 쓰는 형용사야. 매주 같은 시간, 같은 도시락통이 비어서 돌아오는 건 확실히 suspicious하지. (CEFR B1)', 's로 시작, 동사 suspect(의심하다)와 한 가족인 형용사', '[]'),
(7, 1, 373, 'JA', '매주 수요일 유실물센터로 내려오는 ''도시락''을 뜻하는 일본어 단어는?', '["眼鏡(めがね)","財布(さいふ)","荷物(にもつ)","弁当(べんとう)"]', '弁当(べんとう)', '''弁当(べんとう)''는 도시락이라는 뜻이야. 도시락통은 ''弁当箱(べんとうばこ)''라고 해. 이야기 속에서 매주 수요일 비어 있는 채로 내려오는 그 물건이지. (JLPT N5)', '''当''은 ''딱 맞다''는 뜻으로, 끼니 때에 맞춰 싸서 들고 다니는 음식이야', '[]'),
(7, 1, 373, 'ZH', '매주 수요일마다 깨끗이 씻긴 빈 도시락통이 유실물센터로 내려오는 상황을 보고 해수가 느낀 감정은 ''이상하다''였어. 이때 쓸 수 있는 중국어 표현은?', '["复杂(fùzá)","熟悉(shúxī)","普通(pǔtōng)","奇怪(qíguài)"]', '奇怪(qíguài)', '''奇怪(qíguài)''는 ''이상하다, 기이하다''라는 뜻이야. 버릴 거면 그냥 버리지, 굳이 씻어서 물기까지 닦아 맡기는 행동이 딱 奇怪한 상황이지. 熟悉(익숙하다), 普通(평범하다), 复杂(복잡하다)와 헷갈리지 않게 기억해두자. (HSK 3급)', 'qí로 시작하는 2글자 형용사', '[]'),
(7, 2, 373, 'EN', 'From the second week, Haesu started to ______ track of the four-digit numbers written inside the lid.', '["take","hold","make","keep"]', 'keep', '''keep track of''는 어떤 것의 변화나 정보를 계속 기록하고 파악한다는 뜻의 콜로케이션이야. 해수가 매주 바뀌는 숫자를 대장에 따로 적어두며 흐름을 놓치지 않으려는 상황에 딱 맞지. 반대 표현은 ''lose track of''(놓치다). hold/take/make는 track과 함께 쓰이지 않아. (CEFR B1)', '반대말은 ''lose ___ of'' — 계속 쥐고 있는 느낌의 동사', '[]'),
(7, 2, 373, 'JA', '弁当箱(べんとうばこ)は洗(あら)ってあって、水気(みずけ)まで______、ふたが斜(なな)めに乗(の)せてあった。\n(도시락통은 씻겨 있었고, 물기까지 닦아내서 뚜껑이 비스듬히 얹혀 있었다)', '["拭き直して(ふきなおして)","拭き忘れて(ふきわすれて)","拭き始めて(ふきはじめて)","拭き取って(ふきとって)"]', '拭き取って(ふきとって)', '''拭き取る(ふきとる)''는 ''닦아내다''라는 뜻의 복합동사야. 물기나 얼룩을 닦아서 완전히 없앤다는 결과까지 담고 있어서, 씻고 물기까지 말끔히 처리해둔 도시락통 묘사에 딱 맞아. 拭き直す(다시 닦다), 拭き忘れる(닦는 걸 잊다), 拭き始める(닦기 시작하다)는 각각 반복·망각·시작을 나타내서 이 문맥에는 안 맞아. (JLPT N2)', '''拭''은 손(扌)으로 훔쳐 닦는다는 뜻, 뒤에 붙는 ''取''는 ''완전히 없애 버린다''는 결과를 더해주는 한자야', '[]'),
(7, 2, 373, 'ZH', '每周三都出现的空饭盒______了他的注意，他开始在登记簿上做记号。(매주 수요일 나타나는 빈 도시락통이 그의 주의를 끌었다)', '["提高(tígāo)","发生(fāshēng)","举行(jǔxíng)","引起(yǐnqǐ)"]', '引起(yǐnqǐ)', '''引起注意(yǐnqǐ zhùyì)''는 ''주의를 끌다''라는 고정 배합이야. 引起는 注意, 误会, 重视처럼 추상적인 결과를 ''불러일으킬'' 때 써. 发生(발생하다)은 사건이 저절로 일어나는 거고, 举行(개최하다), 提高(높이다)는 이 자리에 안 맞아. (HSK 4급)', '''주의를 끌다''의 동사, yǐn으로 시작하는 2글자', '[]'),
(7, 3, 373, 'EN', '''버릴 거면 그냥 버리면 될 걸, 굳이 씻어서 맡긴다니 — 뭔가 앞뒤가 맞지 않았다''\n\nSomething about the empty lunchbox just didn''t ______ ______.\n(뜻: 앞뒤가 맞지 않다, 말이 안 되다)', '[]', 'add up', '''not add up''은 계산이 안 맞듯 정황이 앞뒤가 안 맞아 수상하다는 뜻의 관용표현이야. 추리물에서 탐정이 단서를 보고 ''뭔가 이상한데''라고 느낄 때 딱 쓰는 말이지. 씻고 물기까지 닦아서 유실물로 보내는 행동이 논리적으로 설명이 안 되니까 딱 맞는 표현이야. ''make sense''도 비슷하게 쓸 수 있지만, ''add up''이 ''조각들을 맞춰보니 어긋난다''는 수사적 뉘앙스를 더 잘 살려줘. (CEFR C1)', '숫자를 쭉 더했는데 합계가 안 맞을 때 그 동사 + u_ (2단어)', '["add up","make sense","quite add up","add up."]'),
(7, 3, 373, 'JA', '''뭔가 석연치 않아서 계속 마음에 걸리다''\n\n捨てるなら普通に捨てればいいのに——あの弁当箱のことが、どうも______。\n(뜻: 아무래도 마음에 걸린다)', '[]', '引っかかる', '''引っかかる(ひっかかる)''는 원래 ''무언가에 걸리다''라는 뜻인데, 비유적으로 ''뭔가 석연치 않아 마음에 걸리다''라는 의미로 자주 써. 단순히 궁금한 ''気になる''보다, 논리적으로 앞뒤가 안 맞아서 찜찜하다는 뉘앙스가 강해. 해수가 빈 도시락통에 의심을 품고 대장에 표시를 남기기 시작한 상황에 딱 맞는 표현이야. (JLPT N2)', 'ひ＋4글자 (무언가에 ''걸려서'' 넘어가지 않는 느낌의 동사)', '["引っかかる","ひっかかる","引っ掛かる","引っかかった","ひっかかった","気にかかる","きにかかる"]'),
(7, 3, 373, 'ZH', '''(일이) 수상쩍다, 석연치 않다''\n\n这件事有点______，每周三都有人把洗得干干净净的空饭盒送到失物招领处。\n(뜻: 이 일은 좀 수상쩍다)', '[]', '蹊跷', '''蹊跷(qīqiāo)''는 단순히 이상한 게 아니라 ''뭔가 사연이나 숨은 내막이 있어 보인다''는 수상쩍음을 나타내는 말이야. ''奇怪(qíguài)''는 그냥 신기하다·이상하다 정도고, ''可疑(kěyí)''는 특정 사람이나 물건을 의심할 때 쓰지. 매주 수요일 같은 시각에 깨끗이 씻긴 빈 도시락통이 내려오는 이 상황은 딱 ''蹊跷''야. (HSK 6급)', 'qī로 시작하는 2글자, ''奇怪''보다 ''뭔가 꿍꿍이가 있다''는 뉘앙스', '["蹊跷","qīqiāo","qīqiao","qiqiao","有蹊跷","很蹊跷"]'),
(7, 1, 386, 'EN', '매주 다른 열차를 골라 타는 게 우연이 아니라 ''일부러, 의도적으로'' 한 일이라는 뜻일 때 쓰는 부사는?', '["at random","in advance","by mistake","on purpose"]', 'on purpose', '''on purpose''는 ''일부러, 고의로''라는 뜻이야. 반대로 ''by mistake''는 ''실수로'', ''at random''은 ''무작위로''라는 뜻이라 여기선 안 맞지. 매주 열차를 바꿔 타는 게 우연이 아니라 의도적이라는 상황이니까 ''on purpose''가 딱이야. (CEFR B1)', 'on으로 시작하는 부사, ''목적(purpose)''과 짝꿍', '[]'),
(7, 1, 386, 'JA', '''매주(일주일마다)''를 뜻하는 일본어 표현으로 알맞은 것은?', '["毎年(まいとし)","毎週(まいしゅう)","毎日(まいにち)","毎月(まいつき)"]', '毎週(まいしゅう)', '''毎週(まいしゅう)''는 ''매주''라는 뜻이야. 통이 매주 같은 자리에서 발견됐다는 이야기 속 상황에 딱 맞는 단어지. 毎日는 매일, 毎月는 매달, 毎年은 매년이야. (JLPT N4)', '''週''는 쉬엄쉬엄갈 착(辶)에 두루 주(周) — 한 바퀴 빙 돌아 다시 돌아오는 7일을 뜻해', '[]'),
(7, 1, 386, 'ZH', '매주 다른 열차, 다른 시간대로 바꿔 타는 누군가. 이때 ''일부러, 고의로''에 해당하는 중국어 표현은?', '["偶然(ǒurán)","突然(tūrán)","认真(rènzhēn)","故意(gùyì)"]', '故意(gùyì)', '''故意(gùyì)''는 ''일부러, 고의로''라는 뜻이야. 우연이 아니라 의도적으로 열차를 바꿔 탄 상황에 딱 맞는 단어지. 반대로 ''偶然(ǒurán)''은 ''우연히''라는 뜻이야. (HSK 4급)', 'gù로 시작하는 2글자, ''故''가 들어가는 부사', '[]'),
(7, 2, 386, 'EN', '''일부러, 의도적으로'' = d__________\n\nSomeone was ______ switching trains every week to avoid being noticed.\n(뜻: 누군가 눈에 띄지 않으려고 매주 일부러 열차를 바꿔 타고 있었다)', '[]', 'deliberately', '''deliberately''는 우연이 아니라 계획하고 의도해서 그렇게 했다는 뉘앙스야. ''on purpose''와 비슷하지만 좀 더 격식 있는 표현이고, 추리물처럼 ''누군가 계산된 행동을 하고 있다''는 상황에 딱 맞아. 열차와 시간대를 매주 바꾸면서 좌석만 고집한 건 분명 의도적인 행동이지. (CEFR B2)', 'd로 시작, ''on purpose''랑 같은 뜻의 부사 (-ly로 끝남)', '["deliberately","Deliberately","deliberate"]'),
(7, 2, 386, 'JA', '''(물건을) 깜빡 두고 내리다, 잊고 두고 오다''\n\n乗客が電車の中に荷物を______しまったのを見たことはありますか。\n(승객이 열차 안에 짐을 놓고 내린 걸 본 적 있어요?)', '[]', '置き忘れて', '''置き忘れる(おきわすれる)''는 置く(두다) + 忘れる(잊다)가 합쳐진 복합동사로, 물건을 어딘가에 두고 온 걸 깜빡했다는 뜻이야. 열차에 뭔가를 놓고 내리는 상황에 딱 맞는 표현이지. 그냥 ''忘れる''보다 ''어디에 둔 채로 왔다''는 장소 뉘앙스가 살아 있어. (JLPT N2)', 'お＋5글자 (''두다''와 ''잊다'' 두 동사가 합쳐진 복합동사의 て형)', '["置き忘れて","おきわすれて","置き忘れた","おきわすれた","置き忘れる","おきわすれる"]'),
(7, 2, 386, 'ZH', '''일부러, 고의로''\n\n每周都换车，看来有人是______换乘的。\n(뜻: 매주 열차를 바꾸는 걸 보니 누군가 일부러 바꿔 타는 것 같다)', '[]', '故意', '''故意(gùyì)''는 ''일부러, 고의로''라는 뜻으로, 우연(偶然)이나 무심코(无意)와 반대되는 말이야. 열차와 시간대를 매주 바꿔 타는 게 우연이 아니라 계획된 행동이라는 걸 딱 짚어주는 단어지. ''故意换乘(일부러 갈아타다)'', ''不是故意的(고의가 아니었다)''처럼 자주 써. (HSK 4급)', 'gù + yì (2글자), ''옛 故'' + ''뜻 意'' — 우연이 아니라 마음먹고', '["故意","gùyì","guyi","gù yì","gu yi","故意地"]'),
(7, 3, 386, 'EN', '숫자가 나타나는 ''간격이 제멋대로여서 규칙을 전혀 찾을 수 없었다''는 뉘앙스를 가장 잘 살린 문장은?', '["The intervals were negligible.","The intervals were prolonged.","The intervals were consistent.","The intervals were erratic."]', 'The intervals were erratic.', '''erratic''은 규칙 없이 들쭉날쭉하고 예측이 안 되는 상태를 뜻해. 형사가 날짜도, 보관함 번호도 아니고 간격마저 제멋대로라 패턴을 못 찾는 상황에 딱 맞지. ''consistent''는 오히려 일정하다는 반대말이고, ''prolonged''는 길게 늘어진, ''negligible''은 무시해도 될 만큼 미미한이라는 뜻이라 여기선 안 맞아. (CEFR C1)', 'e____ic — 심장박동이 불규칙할 때도 쓰는 단어', '[]'),
(7, 3, 386, 'JA', '열차도 시간대도 매번 바뀌는데 좌석 번호만은 절대 바꾸지 않는 상황이야. 빈칸에 가장 어울리는 표현은?\n\n列車も時間帯も毎週違うのに、座席だけは______6号車4番だった。', '["気まぐれに(きまぐれに)","頑なに(かたくなに)","大まかに(おおまかに)","密かに(ひそかに)"]', '頑なに(かたくなに)', '''頑なに''는 남이 뭐라 해도 태도나 방식을 절대 바꾸지 않는 ''고집스럽게, 완강하게''라는 뜻이야. ''密かに''는 몰래, ''気まぐれに''는 변덕스럽게(이야기 속 ''간격도 제멋대로''에 어울리는 말), ''大まかに''는 대충. 열차는 계속 바뀌는데 좌석만은 끝까지 똑같다는 집요함이니까 頑なに가 딱 맞아. (JLPT N1)', '''頑''은 元(원래 생각) + 頁(머리) — 원래 마음을 굽히지 않는 머리, 즉 굽히지 않는 태도를 뜻하는 な형용사의 부사형', '[]'),
(7, 3, 386, 'ZH', '''조금도 변하지 않고 늘 그대로다''\n\n列车和时间每周都在变，唯独座位______，始终是6号车4号座。\n(뜻: 열차와 시간은 매주 바뀌는데, 좌석만은 한결같이 변하지 않는다)', '[]', '一成不变', '''一成不变(yī chéng bù biàn)''은 한번 정해진 뒤로 조금도 바뀌지 않는다는 뜻의 성어야. 범인이 열차와 시간대는 매번 바꾸면서 좌석만큼은 절대 안 바꾸는 이 장면에 딱 맞지. 비슷해 보이는 ''始终如一(shǐzhōng rú yī)''는 태도·마음이 한결같다는 긍정적 뉘앙스가 강하고, ''固执(gùzhí)''는 사람의 성격이 고집스럽다는 뜻이라 사물·패턴에는 잘 안 써. (HSK 6급)', '''一''로 시작하는 네 글자 성어 — ''한 번 정해진 그대로, 변할 变''이 들어가', '["一成不变","yīchéngbùbiàn","yi cheng bu bian","yichengbubian","yī chéng bù biàn","一成不变(yī chéng bù biàn)"]'),
(7, 1, 399, 'EN', '다음 중 ''알아채다, 눈치채다''를 뜻하는 단어는?', '["discover","notice","mention","remind"]', 'notice', '''notice''는 무언가를 문득 알아채거나 눈치채다라는 뜻이야. 해수가 숫자들이 유실물 접수번호라는 걸 손끝으로 먼저 알아챈 장면에 딱 맞는 단어지. (CEFR A2)', 'n으로 시작하는 6글자, ''주의(note)를 두다'' 느낌', '[]'),
(7, 1, 399, 'JA', '유실물 목록 맨 앞에 있던 ''우산''을 뜻하는 일본어 단어로 알맞은 것은?', '["靴(くつ)","帽子(ぼうし)","鞄(かばん)","傘(かさ)"]', '傘(かさ)', '''傘(かさ)''는 우산이라는 뜻이야. 비 오는 날 쓰는 그 우산이지. 참고로 靴(くつ)는 신발, 鞄(かばん)은 가방, 帽子(ぼうし)는 모자야. (JLPT N5)', '''傘''는 큰 지붕 아래에 사람들이 옹기종기 모여 있는 모양을 그린 한자야', '[]'),
(7, 1, 399, 'ZH', '해수가 3년 전 비 오던 그날을 머릿속에 떠올렸어. 다음 중 ''(지난 일을) 회상하다, 떠올리다''에 해당하는 중국어는?', '["考虑(kǎolǜ)","回忆(huíyì)","忘记(wàngjì)","相信(xiāngxìn)"]', '回忆(huíyì)', '''回忆(huíyì)''는 지난 일을 되돌아보며 떠올린다는 뜻이야. 3년 전 비 오던 날을 회상하는 해수의 장면에 딱 맞지. 考虑(kǎolǜ)는 ''고려하다'', 忘记(wàngjì)는 ''잊다'', 相信(xiāngxìn)은 ''믿다''라서 이 상황과는 안 맞아. (HSK 4급)', 'huí로 시작하는 2글자, ''돌아올 回''가 들어감', '[]'),
(7, 2, 399, 'EN', 'The eight numbers ______ to be lost-and-found reference numbers she had issued herself.', '["turned out","came out","made out","worked out"]', 'turned out', '''turn out (to be)''은 ''알고 보니 ~로 밝혀지다''라는 뜻의 구동사야. 해수가 숫자의 정체를 알아채는 순간에 딱 맞는 표현이지. work out은 ''잘 해결되다'', come out은 ''드러나다/나오다'', make out은 ''알아보다''라서 이 문맥엔 안 맞아. (CEFR B1)', 't로 시작하는 구동사, ''알고 보니 ~였다''', '[]'),
(7, 2, 399, 'JA', 'ノートに並べた番号は、どこかで______のある形式だった。(어디서 본 적 있는 형식이었다)', '["顔見知り(かおみしり)","見覚え(みおぼえ)","聞き覚え(ききおぼえ)","心当たり(こころあたり)"]', '見覚え(みおぼえ)', '''見覚えがある(みおぼえがある)''는 ''어디서 본 적이 있다, 눈에 익다''라는 뜻이야. 해수가 숫자 형식을 보고 ''어디서 많이 봤는데'' 하고 느낀 딱 그 장면이지. 聞き覚え는 들어본 기억, 心当たり는 짚이는 데가 있다, 顔見知り는 얼굴만 아는 사이라서 여기엔 안 맞아. (JLPT N2)', '''見(보다)'' + ''覚え(기억)''가 합쳐진 명사 — 눈이 기억하고 있다는 뜻', '[]'),
(7, 2, 399, 'ZH', '他突然______到，这些数字就是失物招领的编号。(그는 문득 이 숫자들이 유실물 접수번호라는 걸 깨달았다)', '["知识(zhīshi)","意识(yìshí)","认识(rènshi)","常识(chángshí)"]', '意识(yìshí)', '''意识到(yìshí dào)''는 머리로 문득 ''깨닫다, 알아차리다''라는 뜻의 고정 배합이야. 해수가 숫자 형식을 보고 유실물 접수번호라는 걸 알아챈 순간에 딱 맞는 표현이지. 认识(알다·아는 사이), 知识(지식), 常识(상식)은 ''到''와 함께 쓰이지 않아. (HSK 5급)', 'yì + shí, 뒤에 ''到''가 붙어 ''깨닫다''가 되는 2글자 단어', '[]'),
(7, 3, 399, 'EN', '''문득 그 사실이 머릿속에 떠올랐다 / 비로소 깨달았다''\n\nIt suddenly ______ ______ her that the numbers were lost-and-found receipt numbers.\n(뜻: 어떤 사실이 서서히/문득 누군가에게 인식되다, 2단어)', '[]', 'dawned on', '''dawn on someone''은 어떤 사실이 문득 또는 서서히 누군가에게 인식되는 걸 뜻해. ''realize''보다 훨씬 문학적이고, ''내가 알아챘다''가 아니라 ''사실이 나에게 밝아왔다''는 수동적인 뉘앙스가 핵심이야. 손끝이 먼저 알아챘다는 이 장면처럼, 머리보다 감각이 먼저 반응하고 뒤늦게 의미가 떠오르는 순간에 딱 맞는 표현이지. upon을 써도 되고, 더 격식 있게 들려. (CEFR C1)', 'd____ o_ — 해가 밝아오듯(dawn) 머릿속이 환해지는 느낌', '["dawned on","dawn on","dawned upon","dawn upon"]'),
(7, 3, 399, 'JA', '''전에 본 적이 있어서 낯익다''는 뜻의 표현\n\nどこかで______のある番号の形式だった。指先のほうが先に気づいた。\n(뜻: 본 기억이 있는, 낯익은)', '[]', '見覚え', '''見覚え(みおぼえ)''는 ''전에 본 기억''이라는 뜻으로, 「見覚えのある〜」 형태로 ''어디서 본 적 있는, 낯익은''을 표현해. 단순히 ''知っている(알고 있다)''와 달리, 확실치는 않지만 시각적 기억이 남아 있는 미묘한 느낌을 담고 있어서 이 장면처럼 ''어디서 많이 본 형식''에 딱 맞아. 참고로 소리에 대해서는 ''聞き覚え(ききおぼえ)''를 써. (JLPT N1)', 'み＋3글자 / ''보다(見)''와 ''기억하다(覚)''가 합쳐진 명사', '["見覚え","みおぼえ","見覚えのある","みおぼえのある","見おぼえ"]'),
(7, 3, 399, 'ZH', '''문득 모든 것을 깨닫다''\n\n看着笔记本上的数字，海秀______，原来那是失物招领的登记编号。\n(뜻: 숫자들을 보다가 문득 깨달았다 — 그것은 유실물 접수번호였다)', '[]', '恍然大悟(huǎngrán dàwù)', '''恍然大悟(huǎngrán dàwù)''는 안개가 걷히듯 문득 모든 걸 깨닫는다는 뜻의 성어야. 해수가 숫자 형식을 보고 ''아, 유실물 접수번호구나'' 하고 번쩍 알아차리는 순간에 딱 맞지. 비슷해 보이는 ''茅塞顿开(máosè dùnkāi)''는 막혔던 생각이 뚫려 이해된다는 쪽이고, ''将信将疑(jiāngxìn jiāngyí)''는 반신반의, ''一知半解(yìzhī bànjiě)''는 어설프게 아는 상태라 여기엔 안 맞아. (HSK 6급)', 'huǎng으로 시작, 뒤 두 글자는 ''大悟(dàwù)''인 4글자 성어', '["恍然大悟","恍然大悟(huǎngrán dàwù)","huǎngrán dàwù","huangran dawu","huǎngrándàwù","huangrandawu","恍然","huǎngrán","huangran"]'),
(7, 1, 412, 'EN', '다음 중 ''사라지다, 없어지다''를 뜻하는 단어는?', '["disagree","disappear","discover","discuss"]', 'disappear', '''disappear''는 사람이나 물건이 갑자기 보이지 않게 되는 걸 말해. 선로 작업 중에 사람이 사라진 상황에 딱 맞는 단어지. 실종된 사람은 ''a missing person''이라고 해. (CEFR A2)', 'dis-로 시작하는 동사, 마술사가 연기 속에서 하는 그것', '[]'),
(7, 1, 412, 'JA', '''(전철에) 타다''를 뜻하는 일본어 동사로 알맞은 것은?', '["走る(はしる)","降りる(おりる)","止まる(とまる)","乗る(のる)"]', '乗る(のる)', '''乗る(のる)''는 전철이나 버스에 ''타다''라는 뜻이야. 電車に乗る(でんしゃにのる)처럼 조사 に와 함께 써. 반대말은 ''降りる(おりる/내리다)''니까 같이 외워두면 좋아. (JLPT N5)', '''乗''은 나무(木) 위에 사람이 올라타 있는 모습에서 온 한자야', '[]'),
(7, 1, 412, 'ZH', '다음 중 ''사라지다, 자취를 감추다''라는 뜻의 중국어 표현으로 알맞은 것은?', '["出现(chūxiàn)","停止(tíngzhǐ)","改变(gǎibiàn)","消失(xiāoshī)"]', '消失(xiāoshī)', '''消失(xiāoshī)''는 사람이나 사물이 눈앞에서 사라져 보이지 않게 되는 걸 말해. 선로 보수 중에 사람이 사라졌다는 이야기에 딱 맞는 단어야. 반대말은 ''出现(chūxiàn, 나타나다)''이고. (HSK 4급)', 'xiāo로 시작하는 2글자 동사, 出现의 반대말', '[]'),
(7, 2, 412, 'EN', '''(신고·서류를) 접수하다, 제출하다'' = f____\n\nA missing person report was ______, but the case was never closed.\n(뜻: 실종 신고는 접수됐지만, 사건은 끝내 종결되지 않았다.)', '[]', 'filed', '''file a report''는 신고나 보고서를 정식으로 접수·제출한다는 뜻의 콜로케이션이야. ''file a missing person report(실종 신고를 하다)'', ''file a complaint(민원을 제기하다)''처럼 관공서·경찰 관련 상황에서 자주 쓰여. 여기서는 신고가 접수된 쪽이라 수동태 ''was filed''가 됐어. (CEFR B2)', '컴퓨터 ''파일''과 똑같이 생긴 단어, 과거형으로 -d 붙여줘 📁', '["filed","Filed","file","File","was filed"]'),
(7, 2, 412, 'JA', '''행방불명, 실종''\n\n線路の補修作業中に、作業員が一人______になった。\n(선로 보수 작업 중에 작업원 한 명이 행방불명이 되었다)', '[]', '行方不明(ゆくえふめい)', '''行方不明(ゆくえふめい)''는 사람의 간 곳을 알 수 없는 상태, 즉 행방불명·실종을 뜻해. 뉴스나 신고서에서 자주 쓰이는 표현이라 ''行方不明になる(행방불명이 되다)'', ''行方不明者(실종자)'' 형태로 통째로 외워두면 좋아. 참고로 단순히 ''없어지다''는 なくなる, ''사라지다''는 消える지만, 사람이 실종된 공적인 상황에는 行方不明을 써. (JLPT N2)', 'ゆ＋5글자 — ''간 곳(行方)''을 알 수 없다(不明)는 뜻의 한자 4글자 단어', '["行方不明","ゆくえふめい","行方不明(ゆくえふめい)","ゆくえふめいに","行方不明に"]'),
(7, 2, 412, 'ZH', '''남겨 두다, 그대로 보존하다''\n\n她每年都把那个箱子从销毁名单里拿出来，一直______着。\n(뜻: 그녀는 매년 그 상자를 폐기 목록에서 빼내 계속 남겨 두었다)', '[]', '保留(bǎoliú)', '''保留(bǎoliú)''는 버리지 않고 남겨 두다, 보존하다라는 뜻이야. ''保留意见(의견을 유보하다)'', ''保留传统(전통을 보존하다)''처럼 자주 쓰여. 창고 안쪽 선반에 3년 넘게 상자를 그대로 둔 그 여자의 행동이 딱 ''保留''지. 비슷한 保存(보관하다)과 달리 ''일부러 없애지 않고 두다''라는 뉘앙스가 강해. (HSK 5급)', 'bǎo + liú, ''지킬 保''로 시작하는 2글자', '["保留","bǎoliú","baoliu","bao liu","bǎo liú","保留(bǎoliú)"]'),
(7, 3, 412, 'EN', '''규정대로면 버려야 하는데, 차마 버릴 마음이 안 들었다''\n\nI couldn''t ______ ______ ______ throw the box away.\n(뜻: 차마 ~할 수가 없었다 / 마음이 내키지 않아 못 했다)', '[]', 'bring myself to', '''can''t bring oneself to (do)''는 하기 싫거나 마음이 아파서 ''차마 ~하지 못하다''라는 뉘앙스야. 여자는 규정상 폐기해야 하는 상자를 매년 목록에서 빼뒀는데, 그건 단순히 잊은 게 아니라 차마 버릴 수 없었던 거지. 비슷해 보이는 ''couldn''t manage to''는 능력 부족, ''refused to''는 의도적 거부라서 이 미묘한 감정을 담지 못해. (CEFR C1)', 'b____ + myself + t_ (3단어, ''가져오다'' 동사로 시작해)', '["bring myself to","bring myself to,","bring my self to","brought myself to"]'),
(7, 3, 412, 'JA', '보관 기한이 지난 분실물을 규정에 따라 ''폐기한다''고 할 때, 가장 적절한 일본어 표현은?', '["廃棄(はいき)する","放棄(ほうき)する","破棄(はき)する","撤去(てっきょ)する"]', '廃棄(はいき)する', '''廃棄する''는 쓸모없어진 물건을 규정·절차에 따라 처분해 없애는 거야. 보관 기한 지난 유실물 처리에 딱 맞는 말이지. ''破棄する''는 계약서나 서류, 약속을 무효로 만들어 찢어 없애는 것, ''放棄する''는 권리나 의무 같은 걸 스스로 포기하는 것, ''撤去する''는 설치돼 있던 건물·시설을 걷어내 치우는 것이라 물건 폐기에는 안 어울려. (JLPT N1)', '''廃''는 집(广)이 무너져 더 이상 쓸 수 없게 된 모습 — 못 쓰게 된 물건을 없애 버리는 것', '[]'),
(7, 3, 412, 'ZH', '''행방이 묘연하다, 어디로 갔는지 알 수 없다''\n\n那个人在铁轨维修中失踪了，至今______不明。\n(뜻: 그 사람은 선로 보수 중 실종되어, 지금까지 행방을 알 수 없다)', '[]', '下落', '''下落不明(xiàluò bùmíng)''은 행방이 묘연하다, 소재를 알 수 없다는 뜻이야. 실종 신고만 접수되고 결론이 안 난 이 상황에 딱 맞는 표현이지. 비슷한 ''失踪(shīzōng)''은 ''실종되다''라는 동작 자체를 말하고, ''下落不明''은 그 후로 어디 있는지 파악이 안 되는 상태를 강조해. ''不见了''는 그냥 ''없어졌다''는 가벼운 구어라 공식 기록에는 안 어울려. (HSK 6급)', '''아래로 떨어지다''의 두 글자 — xià로 시작하는 2글자 + 不明', '["下落","xiàluò","xialuo","下落不明","xiàluò bùmíng","xialuo buming"]'),
(7, 1, 426, 'EN', '여덟 주 동안 이어지던 도시락이 이제 ''더 이상'' 놓이지 않게 된 상황이야. ''더 이상 ~하지 않다''를 뜻하는 영어 표현은?', '["at least","as usual","once again","no longer"]', 'no longer', '''no longer''는 ''더 이상 ~하지 않다''라는 뜻이야. The lunchbox no longer appeared. 처럼 쓰면 돼. 매주 반복되던 일이 끝났다는 마지막 장면에 딱 맞는 표현이지. (CEFR B1)', '두 단어, ''no''로 시작하고 ''길다(long)''와 사촌인 단어가 뒤에 와', '[]'),
(7, 1, 426, 'JA', '이야기의 마지막 장면이야. 그 수요일, 4호선에서는 아무것도 ''내려오지'' 않았어. 다음 중 ''(탈것에서) 내리다''를 뜻하는 일본어 동사는?', '["止まる(とまる)","上がる(あがる)","降りる(おりる)","走る(はしる)"]', '降りる(おりる)', '''降りる(おりる)''는 전철이나 버스에서 내릴 때 쓰는 기본 동사야. 電車を降りる(でんしゃをおりる)처럼 쓰지. 마지막 수요일엔 도시락도, 그녀도 내려오지 않았다는 여운 있는 마무리였어. 上がる는 올라가다, 止まる는 멈추다, 走る는 달리다라는 뜻이야. (JLPT N4)', '''降''은 언덕(阝)에서 아래쪽으로 발을 옮겨 내려오는 모습을 나타낸 한자야', '[]'),
(7, 1, 426, 'ZH', '매주 그 자리에 놓이던 도시락통이 이날은 ''나타나지'' 않았어. 다음 중 ''나타나다, 모습을 드러내다''의 중국어 표현으로 알맞은 것은?', '["实现(shíxiàn)","发现(fāxiàn)","出现(chūxiàn)","表现(biǎoxiàn)"]', '出现(chūxiàn)', '''出现(chūxiàn)''은 없던 것이 나타나다, 모습을 드러내다라는 뜻이야. 마지막 수요일엔 도시락통이 더 이상 ''出现''하지 않았지. 참고로 发现(fāxiàn)은 ''발견하다'', 表现(biǎoxiàn)은 ''표현하다·태도'', 实现(shíxiàn)은 ''실현하다''라서 의미가 달라. (HSK 3급)', 'chū로 시작하는 2글자, 发现과 헷갈리기 쉬운 단어', '[]'),
(7, 2, 426, 'EN', 'That Wednesday at 4:30 p.m., nothing ______ from Line 4 — the lunchbox never came again.', '["turned up","turned in","turned down","turned over"]', 'turned up', '''turn up''은 예상 못 한 것이 나타나거나, 잃어버린 물건이 다시 발견될 때 쓰는 구동사야. 유실물 이야기의 마지막 장면에 딱 어울리지. ''turn in''은 제출하다, ''turn down''은 거절하다, ''turn over''는 뒤집다라는 뜻이라 여기선 안 맞아. (CEFR B1)', 'turn + 방향 부사, ''(잃어버린 것이) 불쑥 나타나다''라는 뜻', '[]'),
(7, 2, 426, 'JA', 'その水曜日の午後四時半、4号線からは何も降りてこなかった。八週間続いた弁当が、その日を境に______。(여덟 주 동안 이어지던 도시락이 그날을 기점으로 끊겼다)', '["打ち切った(うちきった)","立ち止まった(たちどまった)","引き返した(ひきかえした)","途絶えた(とだえた)"]', '途絶えた(とだえた)', '''途絶える(とだえる)''는 계속 이어지던 것이 뚝 끊긴다는 뜻의 자동사야. 연락이나 왕래, 습관처럼 반복되던 게 멈출 때 써. 立ち止まる(멈춰 서다)는 사람의 발걸음, 引き返す(되돌아가다)는 왔던 길을 돌아가는 것, 打ち切る(중단하다)는 누군가가 의도적으로 끊어버리는 타동사라 여기엔 안 맞아. 매주 내려오던 도시락이 더는 오지 않게 된 마지막 장면에 딱 어울리는 단어지. (JLPT N2)', '''途''는 쉬엄쉬엄 갈 착(辶)이 들어간 ''길·도중'', ''絶''은 실이 끊어지는 ''끊을 절'' — 이어지던 길이 뚝 끊긴 모양', '[]'),
(7, 2, 426, 'ZH', '''사라지다, 자취를 감추다''\n\n那个星期三下午四点半，4号线上什么也没下来，那个便当盒从此______了。\n(뜻: 그 도시락통은 그때부터 사라졌다)', '[]', '消失(xiāoshī)', '''消失(xiāoshī)''는 있던 것이 흔적 없이 사라진다는 뜻이야. 기다림이 끝나 더 이상 도시락이 내려오지 않는 이 마지막 장면에 딱 맞는 표현이지. 참고로 ''不见了(bújiàn le)''는 ''안 보인다'' 정도의 가벼운 느낌이고, ''消失''는 존재 자체가 사라졌다는 더 완결된 뉘앙스야. (HSK 5급)', 'xiāo + shī, 두 글자 — ''消''로 시작해', '["消失","消失了","xiāoshī","xiaoshi","xiāo shī","xiao shi"]'),
(7, 3, 426, 'EN', '여덟 주 동안 매주 수요일 도시락통이 올라왔지만, 이번엔 아무것도 발견되지 않았어.\n\nThat Wednesday at 4:30 p.m., nothing ______ ______ from Line 4.\n(뜻: (물건 등이) 나타나다, 발견되다)', '[]', 'turned up', '''turn up''은 유실물센터 맥락에서 물건이 ''(우연히) 나타나다, 발견되다''라는 뜻으로 딱 맞는 구동사야. ''appear''보다 훨씬 구어적이고 자연스럽고, 특히 잃어버렸던 게 다시 나올 때 자주 써. ''show up''도 비슷하게 쓸 수 있지만 사람이 나타날 때 더 흔해. 여기선 여덟 주간 이어지던 도시락이 멈춘, 조용한 마무리를 보여주는 문장이야. (CEFR B2)', 't___ u_ (2단어, 잃어버린 물건이 ''툭'' 나타날 때 쓰는 구동사)', '["turned up","turn up","showed up","show up","came up","was turned in"]'),
(7, 3, 426, 'JA', '''오랫동안 이어져 온 일에 완전히 끝을 맺다''\n\n八週間続いた水曜日の儀式に、ついに______を打った。\n(뜻: 종지부를 찍다 = 마침표를 찍다)', '[]', '終止符', '''終止符を打つ(しゅうしふをうつ)''는 길게 이어져 온 일이나 관계에 완전한 끝을 낸다는 뜻의 관용표현이야. 여덟 주 동안 반복되던 도시락 놓기가 그 수요일에 멈춘 장면에 딱 맞지. 단순히 ''終わる''가 ''끝나다''라는 사실만 말한다면, ''終止符を打つ''는 스스로 매듭을 지었다는 무게가 담겨 있어. 비슷한 표현으로 ''幕を下ろす(막을 내리다)'', ''区切りをつける(일단락 짓다)''가 있어. (JLPT N1)', 'しゅ＋3글자, ''끝(終)·멈춤(止)·기호(符)''로 이루어진 한자어 = 마침표', '["終止符","しゅうしふ","終止符を打った","しゅうしふをうった","終止符を打つ"]'),
(7, 3, 426, 'ZH', '''(일이) 일단락되다, 한 매듭이 지어지다''\n\n那天下午四点半，四号线什么也没有送来。持续了八周的等待，终于______。\n(뜻: 여덟 주 동안 이어지던 기다림이 마침내 일단락되었다)', '[]', '告一段落(gào yī duàn luò)', '''告一段落(gào yī duàn luò)''는 어떤 일이 한 단계 마무리되어 일단락되는 걸 뜻해. 도시락도, 매주 수요일의 기다림도 이제 끝났다는 이야기의 마지막 장면에 딱 맞는 표현이야. 비슷해 보이는 ''结束(jiéshù)''는 그냥 ''끝나다''라는 중립적인 말이고, ''半途而废(bàntú ér fèi)''는 중도에 포기하는 거라 뉘앙스가 달라. 참고로 ''尘埃落定(chén''āi luòdìng)''은 ''먼지가 가라앉다'', 즉 결과가 확정됐다는 뜻으로 결말 묘사에 자주 쓰여. (HSK 6급)', '''단락(段落)''이 들어가는 4글자 표현, 첫 글자는 告(gào)', '["告一段落","告一段落(gào yī duàn luò)","gào yī duàn luò","gao yi duan luo","gàoyīduànluò","gaoyiduanluo"]');
INSERT INTO _su_content (content_id, difficulty, script_id, lang_code, question, options, correct_answer, explanation, hint, acceptable_answers) VALUES
(8, 1, 434, 'EN', '다음 홀드로 뛰기 직전에 무서워서 망설이는 상황이야. ''망설이다, 주저하다''를 뜻하는 단어는?', '["handle","hurry","hesitate","hang"]', 'hesitate', '''hesitate''는 무서워서 바로 못 하고 잠깐 멈칫하며 망설이는 걸 말해. 뛰어야 하는데 계속 머뭇거리다 내려온 상황에 딱이야. (CEFR B1)', 'h로 시작, ''헤지테이션''이라는 말 들어봤지?', '[]'),
(8, 1, 434, 'JA', '홀드에서 다음 홀드로 뛰는 게 ''무서워서'' 계속 내려왔다고 할 때, ''무섭다''에 해당하는 일본어는?', '["暑い(あつい)","眠い(ねむい)","怖い(こわい)","痛い(いたい)"]', '怖い(こわい)', '''怖い(こわい)''는 ''무섭다''라는 뜻의 기본 い형용사야. 뛰어서 홀드를 잡는 게 무서워 계속 내려온 상황에 딱 맞지. 참고로 痛い(아프다), 眠い(졸리다), 暑い(덥다)도 자주 쓰이는 기초 형용사니까 같이 외워두면 좋아. (JLPT N5)', '''怖''는 마음(忄)에 천(布)이 덮이듯 오싹해지는 느낌의 한자야', '[]'),
(8, 1, 434, 'ZH', '다음 중 ''무섭다, 두려워하다''의 중국어 표현으로 알맞은 것은?', '["着急(zháojí)","担心(dānxīn)","生气(shēngqì)","害怕(hàipà)"]', '害怕(hàipà)', '''害怕(hàipà)''는 뭔가가 무섭고 두려울 때 쓰는 말이야. 점프하는 게 무서워서 계속 내려온 상황에 딱이지. 担心(dānxīn)은 ''걱정하다'', 着急(zháojí)는 ''조급해하다'', 生气(shēngqì)는 ''화나다''라서 이 상황이랑은 달라. (HSK 3급)', 'hài로 시작하는 2글자, ''怕''가 들어가', '[]'),
(8, 2, 434, 'EN', 'Every time she had to jump for the next hold, fear ______ her back and she climbed down again.', '["held","kept","pulled","took"]', 'held', '''hold someone back''은 두려움이나 망설임 때문에 누군가가 앞으로 나아가지 못하게 막는다는 뜻이야. 다음 홀드로 뛰지 못하고 계속 내려오는 상황에 딱 맞는 표현이지. keep이나 take는 이 자리에 안 어울리고, pull back은 물리적으로 잡아당기는 느낌이 강해. (CEFR B2)', 'h로 시작, ''잡다''의 과거형 — 클라이밍 ''홀드''랑 같은 단어야', '[]'),
(8, 2, 434, 'JA', '背が低いので、初級の課題でも手が______ホールドが多かった。(키가 작아서 초급 문제에서도 손이 닿지 않는 홀드가 많았다)', '["触れない(ふれない)","届かない(とどかない)","届けない(とどけない)","足りない(たりない)"]', '届かない(とどかない)', '''手が届く(てがとどく)''는 손이 닿다라는 뜻의 관용 표현이라, 안 닿을 땐 ''手が届かない''라고 해. 届ける는 ''(무언가를) 전달하다''라서 주어가 달라지고, 足りない는 수량이 부족하다, 触れない는 ''만질 수 없다''라 거리가 멀어 닿지 않는 상황에는 어색해. (JLPT N3)', '''届''은 주검 시(尸) 아래 由가 들어간 글자로, 물건이나 손이 목적지까지 ''도달하다''는 이미지야', '[]'),
(8, 2, 434, 'ZH', '公司大楼三层新开了一家攀岩馆，我一气之下就去______了。(홧김에 등록해버렸다)', '["点名(diǎnmíng)","出名(chūmíng)","报名(bàomíng)","签名(qiānmíng)"]', '报名(bàomíng)', '''报名(bàomíng)''은 학원·수업·대회 같은 데 ''등록하다, 신청하다''라는 뜻의 이합사야. 그래서 ''报了名'', ''报三个月的名''처럼 사이를 벌려 쓸 수도 있어. 签名은 사인하다, 出名은 유명해지다, 点名은 출석 부르다라서 여기선 안 맞아. (HSK 4급)', 'bào + míng — ''이름(名)을 올린다''는 뜻의 이합사', '[]'),
(8, 3, 434, 'EN', '''막판에 겁이 나서 결국 못 하고 포기했다''\n\nRight before the jump, I always ______ my ______ and climbed back down.\n(뜻: 하려던 순간 용기·담력을 잃다)', '[]', 'lost my nerve', '''lose one''s nerve''는 하려고 마음먹었다가 마지막 순간에 담력이 꺾여 못 하는 상황에 쓰는 표현이야. 홀드 앞에서 뛰려다 무서워서 계속 내려온 딱 그 느낌이지. 여기서 nerve는 ''신경''이 아니라 ''용기, 배짱''이라는 뜻이고, 반대로 용기를 내는 건 ''work up the nerve''라고 해. 비슷하게 ''chicken out''도 쓸 수 있는데 이건 좀 더 구어적이고 ''겁쟁이처럼 물러났다''는 놀리는 뉘앙스가 강해. (CEFR C1)', 'l___ my n____ — 여기서 nerve는 ''신경''이 아니라 ''담력''', '["lost my nerve","lose my nerve","losing my nerve","lost her nerve","lost the nerve","lost my nerves"]'),
(8, 3, 434, 'JA', '''무서워서 앞으로 나아가길 망설이기만 했다''\n\n次のホールドを取るには少し飛ばないといけないのに、怖くていつも______を踏んでばかりいた。\n(뜻: 주저하다, 망설이다)', '[]', '二の足', '''二の足を踏む(にのあしをふむ)''는 첫발은 내밀었지만 두 번째 발을 못 떼고 제자리에서 밟기만 한다는 데서 온 관용구로, 두려움이나 부담 때문에 실행을 주저한다는 뜻이야. 홀드를 잡으려면 뛰어야 하는데 무서워서 계속 내려온 상황에 딱 맞지. 비슷한 ''ためらう''는 심리적 망설임 전반을, ''足がすくむ''는 아예 발이 얼어붙어 움직이지 못하는 상태를 나타내는데, 여기선 시도하려다 물러나는 반복적인 주저이므로 ''二の足を踏む''가 가장 자연스러워. (JLPT N1)', 'に＋3글자, ''두 번째 발''을 내딛지 못하고 그 자리에서 밟기만 한다는 관용구', '["二の足","にのあし","二の足を踏んで","にのあしをふんで","二の足を踏む"]'),
(8, 3, 434, 'ZH', '''겁이 나서 뒤로 물러서다, 움츠러들다''\n\n每次要跳的时候，我都因为害怕而______，只好从墙上下来。\n(뜻: 뛰어야 할 때마다 무서워서 물러서고 만다)', '[]', '退缩(tuìsuō)', '''退缩(tuìsuō)''는 두려움이나 어려움 앞에서 뒤로 물러나고 움츠러드는 걸 말해. 홀드를 잡으려면 뛰어야 하는데 무서워서 매번 포기하고 내려오는 상황에 딱이지. 비슷한 ''后退(hòutuì)''는 단순히 물리적으로 뒤로 가는 것, ''犹豫(yóuyù)''는 결정을 못 하고 망설이는 것이라 ''겁먹고 물러서다''라는 뉘앙스는 退缩가 가장 정확해. (HSK 6급)', 'tuì로 시작하는 2글자 — ''물러날 退'' + ''움츠릴 缩''', '["退缩","tuìsuō","tuisuo","退缩了","退缩(tuìsuō)"]'),
(8, 1, 442, 'EN', '다음 중 ''알아차리다, 눈치채다''를 뜻하는 단어는?', '["nod","mention","notice","observe"]', 'notice', '''notice''는 뭔가를 알아차리다, 눈치채다라는 뜻이야. 그 사람이 매트 옆에 계속 서 있다는 걸 어느 순간 알아차린 상황에 딱 맞지. (CEFR A2)', 'n으로 시작하는 6글자, ''주목(note)''과 친척 같은 단어', '[]'),
(8, 1, 442, 'JA', '매트 옆에 계속 ''서 있다''를 나타낼 때 쓰는 일본어 동사로 알맞은 것은?', '["座る(すわる)","走る(はしる)","立つ(たつ)","歩く(あるく)"]', '立つ(たつ)', '''立つ(たつ)''는 ''서다, 서 있다''라는 뜻이야. 매트 옆에 서서 스팟을 봐주고 있었던 그 장면에 딱 맞는 단어지. 座る(すわる)는 앉다, 歩く(あるく)는 걷다, 走る(はしる)는 달리다야. (JLPT N5)', '한자는 사람이 땅(一) 위에 두 발 딛고 있는 모습을 그린 글자야', '[]'),
(8, 1, 442, 'ZH', '일부러 챙겨온 초크백을 두고 "원래 두 개 들고 다닌다"고 둘러대는 상황이야. 다음 중 ''~인 척하다, 가장하다''라는 뜻의 중국어는?', '["保护(bǎohù)","商量(shāngliang)","拒绝(jùjué)","假装(jiǎzhuāng)"]', '假装(jiǎzhuāng)', '''假装(jiǎzhuāng)''은 실제로는 아닌데 그런 척, 아무렇지 않은 척할 때 쓰는 동사야. 초크백을 챙겨왔으면서 "손에 땀이 많아서 원래 두 개 들고 다닌다"고 하는 게 딱 이 표현이지. 保护는 보호하다, 商量은 상의하다, 拒绝는 거절하다라는 뜻이야. (HSK 4급)', 'jiǎ로 시작하는 2글자 동사, ''가짜 假''가 들어가 있어', '[]'),
(8, 2, 442, 'EN', '''(결국) ~인 것으로 밝혀지다'' = t______ out\n\nAt first I thought he was waiting for his turn, but it ______ out he was spotting me the whole time.\n(뜻: 알고 보니 그는 계속 내 스팟을 봐주고 있었던 거였다)', '[]', 'turned', '''turn out (that)~''은 ''알고 보니 ~이더라, ~인 것으로 밝혀지다''라는 뜻의 구동사야. 처음 생각과 실제가 달랐을 때 쓰기 딱 좋은 표현이지. 여기선 과거 이야기니까 ''turned out''이 자연스러워. (CEFR B1)', 't로 시작하는 6글자 동사 + out. ''돌다/변하다''라는 기본 뜻의 그 동사!', '["turned","Turned","turned out","Turned out","turn out","turn"]'),
(8, 2, 442, 'JA', '''(사실과 다르게) 그렇게 믿어버리다, ~인 줄로만 알다''\n\n最初は自分の順番を待っているのだと______いた。でも、私を見てくれていたんだ。\n(처음엔 자기 순서를 기다리는 줄로만 알았어)', '[]', '思い込んで', '''思い込む(おもいこむ)''는 실제와 다른데도 스스로 그렇게 굳게 믿어버리는 걸 말해. 여기선 상대가 자기 차례를 기다리는 줄로만 알았다는 착각 상황이라 딱 맞아. 단순히 ''생각했다''인 ''思った''보다 ''단단히 그렇게 믿고 있었다''는 뉘앙스가 강해. ''込む''는 안쪽으로 밀어 넣는 이미지라, 생각을 마음속에 밀어 넣어 굳혀버린 느낌이야. (JLPT N2)', 'おも＋4글자 (思う + 込む의 복합동사, 「~んで」 형태로)', '["思い込んで","おもいこんで","思いこんで","思い込んでいた","おもいこんでいた"]'),
(8, 2, 442, 'ZH', '''핑계, 구실''\n\n他说自己手容易出汗，所以带两个粉袋，这明显是个______。\n(뜻: 손에 땀이 많아서 초크백을 두 개 들고 다닌다는 건 누가 봐도 핑계였다)', '[]', '借口', '''借口(jièkǒu)''는 ''핑계, 구실''이라는 뜻이야. ''找借口(zhǎo jièkǒu)''는 ''핑계를 대다''라는 고정 배합으로 자주 쓰여. 초크백을 두 개 들고 다닌다는 말이 딱 그 사람의 다정한 借口였던 거지. (HSK 5급)', 'jiè + kǒu (2글자, ''빌릴 借'' + ''입 口''). 동사 找와 자주 붙어 다녀요', '["借口","jièkǒu","jiekou","jiè kǒu","jie kou","借口(jièkǒu)"]'),
(8, 3, 442, 'EN', '''(문득) ~라는 걸 깨닫게 되다''\n\nIt finally ______ ______ me that he wasn''t waiting for his turn — he was spotting me.\n(뜻: 어느 순간 문득 알게 되다)', '[]', 'dawned on', '''dawn on someone''은 새벽(dawn)이 밝아오듯 어떤 사실을 문득 깨닫게 된다는 뜻이야. 그 사람이 자기 순서를 기다린 게 아니라 계속 스팟을 봐주고 있었다는 걸 뒤늦게 알아챈 이 장면에 딱 맞지. ''occurred to me''도 비슷하게 쓸 수 있고, 단순한 realize보다 ''서서히/뒤늦게 알아차림''의 뉘앙스가 강해. (CEFR C1)', 'd___ o_ (2단어) — 해가 뜨듯 서서히 밝아오는 깨달음', '["dawned on","dawn on","dawned upon","occurred to","occured to"]'),
(8, 3, 442, 'JA', '''발목을 접질리다(삐다)''\n\n足首を______しまって、しばらくジムに行けなくなった。\n(뜻: 관절을 비틀어 삐다)', '[]', 'ひねって', '''足首をひねる(あしくびをひねる)''가 발목을 삐다·접질리다에 딱 맞는 표현이야. 한자 ''捻''은 손(扌)으로 비틀어 돌리는 모양이라 ''비틀다''라는 뜻이 되지. 비슷한 ''くじく(挫く)''도 삐다라는 뜻으로 쓰이고, 의학적으로 진단할 때는 ''捻挫する(ねんざする)''라고 해. 참고로 ''ひねる''는 수도꼭지를 돌릴 때(蛇口をひねる)나 머리를 짜낼 때(頭をひねる)도 쓰는 다의어야. (JLPT N2)', 'ひ＋3글자 (관절을 ''비틀다''라는 뜻의 동사 て형)', '["ひねって","捻って","くじいて","挫いて","ねんざして","捻挫して","ねんざしちゃって"]'),
(8, 3, 442, 'ZH', '초크백을 슬쩍 밀어주고는 "손에 땀이 많아서 두 개 들고 다닌다"고 둘러대는 그 사람. 말은 그렇게 해도 진짜 속마음은 따로 있는 상황을 나타내는 표현으로 가장 알맞은 것은?', '["醉翁之意不在酒(zuìwēng zhī yì bù zài jiǔ)","掩耳盗铃(yǎn ěr dào líng)","画蛇添足(huà shé tiān zú)","心不在焉(xīn bù zài yān)"]', '醉翁之意不在酒(zuìwēng zhī yì bù zài jiǔ)', '''醉翁之意不在酒''는 겉으로 내세우는 이유와 진짜 속뜻이 다를 때 쓰는 속담이야. 초크백 핑계(借口)를 대지만 실제로는 다가가고 싶은 마음이 진짜 목적인 거지. ''掩耳盗铃''은 뻔한 걸 자기만 속이는 어리석음, ''画蛇添足''은 쓸데없는 짓을 더하는 것, ''心不在焉''은 그냥 정신이 딴 데 팔린 상태라 맥락에 맞지 않아. (HSK 6급)', '술 취한 노인(翁)이 등장하는 속담, 진짜 뜻은 ''술''에 있지 않아요', '[]'),
(8, 1, 450, 'EN', '다른 홀드는 다 새로 세팅됐는데 초록색 문제만 ''그대로 남아 있었다''고 할 때 쓸 수 있는 단어는?', '["repeat","return","remain","remove"]', 'remain', '''remain''은 바뀌지 않고 그 자리에 계속 남아 있다는 뜻이야. Only the green route remained on the wall처럼 쓸 수 있어. remove(치우다), return(돌아오다), repeat(반복하다)와 헷갈리지 말자. (CEFR B1)', 're-로 시작하는 6글자 동사, ''계속 그 자리에 있다''', '[]'),
(8, 1, 450, 'JA', '사장님은 누구냐고 물어도 대답 없이 그냥 ''웃기만'' 했어. 다음 중 ''웃다''에 해당하는 일본어 동사는?', '["笑う(わらう)","怒る(おこる)","泣く(なく)","驚く(おどろく)"]', '笑う(わらう)', '''笑う(わらう)''는 ''웃다''라는 뜻의 기초 동사야. 사장님이 대답 대신 그냥 웃고 넘기는 장면에 딱 맞지. 泣く는 울다, 怒る는 화내다, 驚く는 놀라다야. (JLPT N5)', '''笑''는 대나무(竹) 아래에서 사람이 몸을 굽히고 웃는 모습에서 온 한자야', '[]'),
(8, 1, 450, 'ZH', '사장님이 "누가 ''계속'' 남겨달라고 한다"고 말했어. 이때 ''계속, 줄곧''에 해당하는 중국어 표현은?', '["一共(yígòng)","一定(yídìng)","一般(yìbān)","一直(yìzhí)"]', '一直(yìzhí)', '''一直(yìzhí)''는 ''줄곧, 계속''이라는 뜻의 부사야. 누군가 한 달 내내 그 초록색 문제를 남겨달라고 계속 부탁했다는 거지. 참고로 一定(반드시), 一共(모두 합쳐), 一般(보통)은 뜻이 전혀 달라. (HSK 3급)', '''곧을 直(직)''이 들어간 2글자 부사 — 쭉 이어지는 느낌', '[]'),
(8, 2, 450, 'EN', 'I kept asking who it was, but the owner just smiled and wouldn''t ______ on.', '["keep","let","hold","give"]', 'let', '''let on''은 알고 있는 걸 남에게 흘리거나 털어놓는다는 뜻의 구동사야. ''wouldn''t let on''이면 알면서도 끝까지 입을 안 여는 상황이지. 사장님이 웃기만 하고 누군지 안 알려준 딱 그 장면이야. give on, hold on, keep on은 다 다른 뜻이라 여기선 안 어울려. (CEFR B2)', 'let + 짧은 전치사 두 글자. ''비밀을 슬쩍 흘리다'' 느낌', '[]'),
(8, 2, 450, 'JA', '誰なのか______けど、社長は笑うだけで教えてくれなかった。(누구냐고 캐물었는데 그냥 웃기만 하고 안 알려주더라)', '["問いかけた(といかけた)","問い合わせた(といあわせた)","問い詰めた(といつめた)","問い返した(といかえした)"]', '問い詰めた(といつめた)', '''問い詰める(といつめる)''는 상대가 말할 때까지 집요하게 캐묻다, 추궁하다라는 뜻이야. 問い合わせる는 (기관 등에) 문의하다, 問いかける는 말을 걸듯 묻다, 問い返す는 되묻다라서 여기선 ''끝까지 캐물었다''는 느낌의 問い詰めた가 딱 맞아. (JLPT N2)', '''問''은 문(門) 앞에서 입(口)으로 묻는 모양, ''詰''은 말(言)로 상대를 꽉 채워 몰아붙이는 느낌', '[]'),
(8, 2, 450, 'ZH', '老板说："有人一直要求______这条绿色线路。"（누군가 계속 이 초록색 루트를 남겨달라고 했다）', '["保护(bǎohù)","保存(bǎocún)","保留(bǎoliú)","保持(bǎochí)"]', '保留(bǎoliú)', '''保留(bǎoliú)''는 없애지 않고 그대로 남겨두다라는 뜻이야. 홀드를 뜯지 않고 그대로 둔 상황에 딱 맞지. 保存(보존하다·저장하다), 保护(보호하다), 保持(어떤 상태를 유지하다)와는 뉘앙스가 달라. 특히 保持는 ''保持安静(조용히 유지하다)''처럼 상태 유지에 쓰여서 여기선 어색해. (HSK 5급)', 'bǎo로 시작하는 2글자, 두 번째 글자는 ''머무를 留''', '[]'),
(8, 3, 450, 'EN', '''누구냐고 계속 캐물었다''\n\nI kept ______ ______ ______ an answer, but he just smiled and said nothing.\n(뜻: ~에게 답을 달라고 계속 압박하며 캐묻다 / 3단어)', '[]', 'pressing him for', '''press someone for something''은 상대가 말하기 꺼리는 걸 계속 압박하면서 캐묻는 뉘앙스야. 그냥 ''ask''는 한 번 물어보는 느낌이라 ''캐물었다''의 집요함이 안 살아. 사장님이 웃고 넘기는데도 계속 물어본 상황이니까 press him for an answer가 딱 맞고, push/pressure/badger him for도 비슷하게 쓸 수 있어. (CEFR C1)', 'p____ him f__ — ''누르다''라는 동사가 사람한테 쓰이면 ''압박해서 캐묻다''', '["pressing him for","press him for","pressing her for","pressing him on","pushing him for","pressuring him for","badgering him for","prodding him for","hounding him for"]'),
(8, 3, 450, 'JA', '''대답을 피하는 상대에게 끈질기게 추궁하듯 캐묻다''\n\n誰なのか______けど、ただ笑うだけで教えてくれなかった。\n(뜻: 캐물었지만)', '[]', '問い詰めた', '''問い詰める(といつめる)''는 그냥 묻는 게 아니라, 얼버무리는 상대를 끝까지 몰아붙이며 캐묻는 뉘앙스야. ''問う(묻다)'' + ''詰める(몰아붙이다, 바짝 조이다)''가 합쳐진 복합동사라서 강도가 세. 비슷한 ''尋ねる(たずねる)''나 ''聞く''는 단순히 물어보는 정도라 ''누구냐고 계속 캐물었다''는 이 장면엔 약해. 참고로 사장님처럼 웃으며 대답을 흐리는 건 ''お茶を濁す'' 또는 ''言葉を濁す''라고 해. (JLPT N1)', 'と＋4글자 / ''묻다(問う)''에 ''몰아붙이다(詰める)''가 붙은 복합동사의 과거형', '["問い詰めた","といつめた","問いつめた","問い詰める","といつめる","問い詰めたんだ","問い詰めました"]'),
(8, 3, 450, 'ZH', '''입을 꼭 다물고 비밀을 절대 말하지 않다''를 뜻하는 4글자 성어를 쓰세요.\n\n我追问是谁，老板却只是笑笑，______，一个字也不肯说。\n(뜻: 사장님은 그저 웃기만 하고 입을 꼭 다문 채 한마디도 하려 하지 않았다)', '[]', '守口如瓶(shǒu kǒu rú píng)', '''守口如瓶(shǒu kǒu rú píng)''은 입을 병마개처럼 꽉 막는다는 뜻으로, 비밀을 철저히 지켜 절대 말하지 않는다는 성어야. 비슷해 보이는 ''闭口不谈(bì kǒu bù tán)''은 특정 화제를 아예 언급하지 않는다는 뉘앙스고, ''守口如瓶''은 ''알고 있지만 지켜준다''는 느낌이 강해서 ''누가 남겨달라고 했는지 알면서도 웃기만 하는'' 사장님 상황에 딱 맞아. (HSK 6급)', '입(口)을 ''병(瓶)''처럼 꽉 막는다는 비유 — 守로 시작하는 4글자', '["守口如瓶","守口如瓶(shǒu kǒu rú píng)","shǒu kǒu rú píng","shǒukǒurúpíng","shou kou ru ping","shoukouruping"]'),
(8, 1, 458, 'EN', '다음 중 ''계산하다, 따져보다''를 뜻하는 단어는?', '["celebrate","calculate","continue","complain"]', 'calculate', '''calculate''는 숫자나 순서를 따져서 계산하다라는 뜻이야. 한 달 동안 혼자 발 순서를 다 계산해뒀다는 장면에 딱 맞는 단어지. (CEFR B1)', '계산기(calculator)의 동사형이야', '[]'),
(8, 1, 458, 'JA', '발 위치를 바꾸자 손이 홀드에 ''닿았다''고 할 때, ''닿다''에 해당하는 일본어는?', '["開く(ひらく)","動く(うごく)","届く(とどく)","続く(つづく)"]', '届く(とどく)', '''届く(とどく)''는 손이나 물건이 어떤 지점까지 ''닿다, 도착하다''라는 뜻이야. 手が届いた(손이 닿았다)처럼 쓰지. 続く는 계속되다, 動く는 움직이다, 開く는 열리다라는 뜻이야. (JLPT N4)', '우편물이 ''도착하다''에도 쓰는 한자야. 목표 지점까지 이르렀다는 뜻', '[]'),
(8, 1, 458, 'ZH', '다음 중 ''다치다, 부상을 입다''라는 뜻의 중국어 표현으로 알맞은 것은?', '["摔倒(shuāidǎo)","生病(shēngbìng)","受伤(shòushāng)","感冒(gǎnmào)"]', '受伤(shòushāng)', '''受伤(shòushāng)''은 몸을 다쳐서 부상을 입는 걸 말해. 발목을 다친 상황이니까 딱 이 단어지. ''摔倒(shuāidǎo)''는 넘어지다, ''生病(shēngbìng)''은 병이 나다, ''感冒(gǎnmào)''는 감기에 걸리다라는 뜻이야. (HSK 4급)', 'shòu로 시작하는 2글자, ''받다 + 상처''의 조합', '[]'),
(8, 2, 458, 'EN', '''알아내다, 파악하다'' = f______ out\n\nHe had already ______ out the entire foot sequence by himself.\n(뜻: 그는 이미 발 순서를 혼자 다 알아내 놨다)', '[]', 'figured', '''figure out''은 머리를 써서 답이나 방법을 알아낸다는 뜻의 구동사야. 한 달 동안 그 구간 발 순서를 혼자 다 계산해뒀다는 상황에 딱 맞지. 여기선 ''had + p.p.'' 형태라 figured가 정답. (CEFR B1)', 'f로 시작, ''숫자/몸매''라는 뜻의 명사와 똑같이 생긴 동사 (과거형으로!)', '["figured","Figured","figured out","Figured out","figure out","figure"]'),
(8, 2, 458, 'JA', '''(다리를) 절뚝거리다, 질질 끌다''\n\nこの前、足を______ながら靴を履き替えているのを見られていた。\n(지난번에 다리를 절뚝거리면서 신발 갈아신는 걸 들켰다)', '[]', '引きずり', '''足を引きずる(あしをひきずる)''는 다리를 질질 끌다, 즉 절뚝거리며 걷는다는 뜻의 관용 표현이야. 여기서는 ながら 앞이라 ''引きずり''가 돼. 단순히 다치는 걸 뜻하는 怪我する와 달리, 상대가 ''걷는 모습''을 보고 눈치챘다는 장면에 딱 맞는 말이지. (JLPT N2)', 'ひ＋3글자 / 「引く(끌다)」에서 온 복합동사, 발을 땅에서 못 떼고 끌듯이 걷는 모습', '["引きずり","ひきずり","引き摺り","引きずりながら","ひきずりながら","引きずる","ひきずる"]'),
(8, 2, 458, 'ZH', '''다치다, 부상을 입다''\n\n我没告诉任何人我的脚______了，可他一看就发现了。\n(뜻: 발을 다친 걸 아무한테도 말 안 했는데, 그 사람은 보자마자 알아챘다)', '[]', '受伤', '''受伤(shòushāng)''은 ''상처를 받다'' 즉 다치다, 부상을 입다라는 뜻이야. ''受'' + ''伤''으로 나눌 수 있는 이합사라서 ''受了伤(다쳤다)'', ''受过伤(다친 적 있다)''처럼 중간에 了/过를 넣어 쓸 수도 있어. 발목을 삐거나 다쳤을 때 ''脚受伤了''라고 하면 딱 자연스러워. (HSK 4급)', 'shòu + shāng — ''받을 受'' + ''상처 伤'', 중간에 ''了''가 끼어들 수도 있는 이합사', '["受伤","受伤(shòushāng)","shòushāng","shoushang","shòu shāng","shou shang"]'),
(8, 3, 458, 'EN', '말한 적도 없는 발목 부상을, 절뚝거리며 신발 갈아신는 모습만 보고 그 사람이 알아챘어. 이 ''작은 단서를 포착해 눈치채다''를 가장 자연스럽게 표현한 문장은?', '["He let it slide without me ever saying a word.","He picked up on it without me ever saying a word.","He brushed it off without me ever saying a word.","He took it in stride without me ever saying a word."]', 'He picked up on it without me ever saying a word.', '''pick up on something''은 남이 말해주지 않은 미묘한 신호나 단서를 알아채는 걸 뜻해. 딱 이 상황이지. ''brush it off''는 별거 아닌 듯 무시하는 것, ''let it slide''는 알고도 그냥 넘어가 주는 것, ''take it in stride''는 힘든 일을 담담히 받아들이는 것이라 ''눈치챘다''는 의미와는 완전히 달라. (CEFR C1)', 'p___ u_ o_ (3단어) — 라디오가 약한 신호를 ''잡아내는'' 그 느낌', '[]'),
(8, 3, 458, 'JA', '''다친 발을 끌면서(절뚝거리면서) 신발을 갈아신었다''는 상황을 일본어로 가장 자연스럽게 표현한 것은?', '["足を組みながら靴を履き替えていた","足を伸ばしながら靴を履き替えていた","足を引きずりながら靴を履き替えていた","足を運びながら靴を履き替えていた"]', '足を引きずりながら靴を履き替えていた', '''足を引きずる(あしをひきずる)''는 다치거나 힘이 없어서 발을 질질 끌며 걷는 모습, 즉 ''절뚝거리다''에 딱 맞는 표현이야. ''足を伸ばす''는 다리를 쭉 뻗는 것, ''足を組む''는 다리를 꼬는 것, ''足を運ぶ''는 일부러 어딘가에 찾아간다는 관용표현이라 부상 상황과는 안 맞아. 그 사람이 이 미묘한 걸음걸이까지 눈치챘다는 게 포인트지. (JLPT N2)', '''引''은 활(弓)을 당기는 모양 — 발을 바닥에 ''끌어당기며'' 걷는 그림. 뒤에 붙는 ''~ずる''가 무게감을 더해줘', '[]'),
(8, 3, 458, 'ZH', '다친 발목 때문에 뛰지 못하는 걸 알고, 한 달 내내 혼자 발 순서를 계산해둔 그 사람의 마음을 표현하기에 가장 알맞은 성어는?', '["用心良苦(yòngxīn liángkǔ)","别有用心(bié yǒu yòngxīn)","三心二意(sān xīn èr yì)","半途而废(bàn tú ér fèi)"]', '用心良苦(yòngxīn liángkǔ)', '''用心良苦''는 남을 위해 보이지 않는 곳에서 애써 마음을 쓰고 고심했다는 뜻이야. 한 달 동안 몰래 발 순서까지 계산해둔 상황에 딱 맞지. ''别有用心''은 딴 속셈이 있다는 부정적인 뜻, ''三心二意''는 마음이 갈팡질팡하다, ''半途而废''는 중도에 포기하다라는 뜻이라 맥락에 안 맞아. (HSK 6급)', '마음을 쓰다(用心) + 고생스럽다(苦) → 4글자', '[]'),
(8, 1, 469, 'EN', '상대방 마음이 뭔지 몰라서 머릿속이 뒤죽박죽인 상태를 표현할 때, ''혼란스러운, 헷갈리는''에 해당하는 단어는?', '["confused","connected","concerned","confident"]', 'confused', '''confused''는 상황이나 감정이 정리가 안 돼서 헷갈리는 상태를 말해. 마지막에 ''아직도 모르겠음''이라고 한 그 마음이 딱 I''m still confused야. confident는 ''자신 있는'', concerned는 ''걱정하는''이라 뉘앙스가 달라. (CEFR A2)', 'con-으로 시작하는 형용사, 머릿속이 엉킨 느낌', '[]'),
(8, 1, 469, 'JA', '이 사람 마음이 뭔지 결국 결론을 못 낸 상태야. ''아직 모르겠다(まだ〜ない)''라고 말할 때, 밑줄에 들어갈 ''알다, 이해하다''의 일본어 동사로 알맞은 것은?', '["忘れる(わすれる)","考える(かんがえる)","分かる(わかる)","覚える(おぼえる)"]', '分かる(わかる)', '''分かる(わかる)''는 ''알다, 이해하다''라는 뜻이야. 마지막 문장처럼 아직 결론이 안 났을 때는 ''まだ分からない(아직 모르겠어)''라고 하면 딱 맞아. 覚える는 기억하다, 忘れる는 잊다, 考える는 생각하다라서 여기엔 안 맞지. (JLPT N5)', '''分''은 여덟(八)을 칼(刀)로 갈라 나누는 모양 — 나눠서 구분하면 ''알게'' 되지', '[]'),
(8, 1, 469, 'ZH', '먼저 물어볼지 말지 결정하지 못하고 마음이 왔다 갔다 하는 상태. 이 ''망설이다''에 해당하는 중국어 표현은?', '["后悔(hòuhuǐ)","怀疑(huáiyí)","决定(juédìng)","犹豫(yóuyù)"]', '犹豫(yóuyù)', '''犹豫(yóuyù)''는 이럴까 저럴까 결정을 못 내리고 망설인다는 뜻이야. 물어볼까 말까 하면서 시간표만 붙잡고 보던 마지막 장면의 마음이 딱 이거지. 참고로 怀疑는 의심하다, 决定은 결정하다, 后悔는 후회하다야. (HSK 4급)', 'yóu로 시작하는 2글자 동사', '[]'),
(8, 2, 469, 'EN', 'Is he into me, or is he just a nice guy? Even now, I can''t ______ my head around it.', '["wrap","twist","bend","spin"]', 'wrap', '''can''t wrap my head around it''은 아무리 생각해도 이해가 안 된다, 도무지 감이 안 잡힌다는 뜻의 관용 표현이야. 이야기 마지막의 ''아직도 모르겠음'' 그 답답한 마음에 딱 맞는 표현이지. twist/spin/bend는 물리적으로 비틀거나 구부린다는 뜻이라 여기선 안 어울려. (CEFR B2)', '선물 포장할 때 쓰는 그 동사, w로 시작', '[]'),
(8, 2, 469, 'JA', 'この気持ちが何なのか、______よく分からない。(이 마음이 뭔지, 아직도 잘 모르겠다)', '["直ちに(ただちに)","早速(さっそく)","次第に(しだいに)","未だに(いまだに)"]', '未だに(いまだに)', '''未だに(いまだに)''는 ''아직까지도, 여전히''라는 뜻으로, 시간이 꽤 지났는데도 상태가 안 변했을 때 쓰는 부사야. 이야기 마지막의 ''아직도 모르겠음''처럼 답을 못 낸 마음에 딱 맞아. 直ちに(즉시), 次第に(점차), 早速(당장, 곧바로)와 헷갈리지 말자. (JLPT N2)', '''未''는 ''아직 오지 않음''(未来의 未)을 뜻하는 한자야. 예상보다 오래 그 상태가 이어질 때 쓰는 부사.', '[]'),
(8, 2, 469, 'ZH', '要不要主动问他的名字，我到现在还在______。(아직도 망설이는 중이다)', '["后悔(hòuhuǐ)","拒绝(jùjué)","冷静(lěngjìng)","犹豫(yóuyù)"]', '犹豫(yóuyù)', '''犹豫(yóuyù)''는 마음을 정하지 못하고 망설이는 상태를 말해. ''还在犹豫(아직 망설이는 중)''처럼 자주 쓰이지. 물어볼까 말까 고민하는 마지막 장면에 딱 맞는 단어야. 后悔(후회하다), 冷静(침착하다), 拒绝(거절하다)와 헷갈리지 말자. (HSK 4급)', 'yóu로 시작하는 2글자, ''결정 못 하고 왔다 갔다'' 하는 마음', '[]'),
(8, 3, 469, 'EN', '''먼저 물어볼까, 아니면 그냥 모른 척할까 — 아직도 마음을 못 정했다''\n\nShould I be the one to ask first? Honestly, I''m still ______ ______ ______ about it.\n(뜻: 두 가지 사이에서 마음을 정하지 못한, 갈팡질팡하는)', '[]', 'in two minds', '''be in two minds (about something)''은 두 선택지 사이에서 마음을 정하지 못하고 갈팡질팡하는 상태를 말해. 미국식으로는 ''of two minds''라고 쓰고, ''on the fence''도 결정을 못 내리고 중립에 머물러 있다는 비슷한 뉘앙스야. 그냥 ''I don''t know''보다 ''두 마음이 계속 부딪히는'' 지속적인 망설임을 훨씬 정확하게 담아내는 표현이라, 마지막 문장의 ''아직도 모르겠음''에 딱 맞아. (CEFR C1)', '숫자 2가 들어가는 3단어 표현 — 마음이 둘로 갈린 상태', '["in two minds","of two minds","on the fence","torn two ways"]'),
(8, 3, 469, 'JA', '''상대 마음이 뭔지 확실하지 않아서 개운하지 않고 찝찝한 상태''\n\n本当に私に気があるのか、ただの親切なのか。今も気持ちが______している。\n(뜻: 마음이 개운치 않고 답답하게 뭉쳐 있다)', '[]', 'もやもや', '''もやもや''는 안개(靄)가 낀 것처럼 마음속이 뿌옇고 정리되지 않아 답답한 상태를 나타내는 의태어야. 비슷해 보이는 ''いらいら''는 짜증, ''そわそわ''는 안절부절, ''うずうず''는 하고 싶어 근질거리는 느낌이라 결이 달라. 여기선 ''좋아하는 건지 그냥 친절한 건지 몰라 찝찝한'' 딱 그 감정이라 もやもや가 제일 자연스러워. (JLPT N1)', 'も＋3글자, 안개처럼 뿌옇게 낀 느낌을 나타내는 의태어', '["もやもや","モヤモヤ","もやもやして","モヤモヤして","もやもやした"]'),
(8, 3, 469, 'ZH', '''(마음이 어지러워) 도무지 갈피를 못 잡고 혼란스럽다''\n\n到现在我还是很______，搞不清他对我到底是什么心思。\n(뜻: 지금까지도 여전히 혼란스러워서, 그 사람 마음이 뭔지 알 수가 없다)', '[]', '困惑(kùnhuò)', '''困惑(kùnhuò)''는 상황이나 상대의 속마음을 알 수 없어서 머릿속이 정리 안 되고 혼란스러운 상태를 말해. 마지막 문장 ''아직도 모르겠음''의 그 답답한 느낌에 딱이야. 비슷한 ''迷茫(mímáng)''은 앞날이 안 보여 막막한 느낌이라 좀 더 무겁고, ''疑惑(yíhuò)''는 ''의심''이 섞여 있어서 뉘앙스가 달라. 더 강조하고 싶으면 ''困惑不解(kùnhuò bùjiě)''라고 쓸 수도 있어. (HSK 6급)', 'kùn으로 시작하는 2글자, ''곤란할 困'' + ''미혹할 惑''', '["困惑","kùnhuò","kunhuo","kùn huò","困惑不解","kùnhuò bùjiě"]');
INSERT INTO _su_content (content_id, difficulty, script_id, lang_code, question, options, correct_answer, explanation, hint, acceptable_answers) VALUES
(9, 1, 481, 'EN', '3년 내내 같은 김밥만 먹어서 ''지겨운, 질린'' 상태를 나타내는 영어 표현으로 알맞은 것은?', '["boring","bored","bothered","brave"]', 'bored', '''bored''는 사람이 지겨움을 느끼는 상태를 말해. ''be bored with ~''로 쓰면 ''~에 질리다''라는 뜻이 돼. 참고로 ''boring''은 지루하게 만드는 대상에 쓰는 말이라, 하윤의 기분에는 ''bored''가 맞아. (CEFR B1)', '''지루한''이라는 뜻의 그 단어, b로 시작해', '[]'),
(9, 1, 481, 'JA', '엄마가 대답 없이 ''웃기만 했다''고 할 때, ''웃다''에 해당하는 일본어 동사는?', '["泣く(なく)","怒る(おこる)","困る(こまる)","笑う(わらう)"]', '笑う(わらう)', '''笑う(わらう)''는 ''웃다''라는 뜻이야. 엄마가 딸의 투정에 대답 대신 그냥 웃기만 한 장면에 딱 맞는 기초 동사지. 泣く는 울다, 怒る는 화내다, 困る는 곤란하다는 뜻이야. (JLPT N5)', '''笑''는 대나무(竹) 아래에서 사람이 몸을 굽히며 소리 내는 모양이야', '[]'),
(9, 1, 481, 'ZH', '밥이 너무 ''짜다''고 할 때 쓰는 중국어 표현으로 알맞은 것은?', '["辣(là)","甜(tián)","酸(suān)","咸(xián)"]', '咸(xián)', '''咸(xián)''은 소금기가 많아 ''짜다''는 뜻이야. 甜(tián)은 달다, 酸(suān)은 시다, 辣(là)는 맵다니까 헷갈리지 말자. 김밥 밥이 너무 짜서 물을 세 번이나 마신 장면에 딱 맞는 단어지. (HSK 4급)', '소금 맛! xi로 시작하는 한 글자', '[]'),
(9, 2, 481, 'EN', 'From September, the taste of the kimbap started to seem slightly ______ — something just wasn''t right.', '["down","off","over","out"]', 'off', '음식이나 맛에 대해 ''taste/smell off''라고 하면 ''맛이 이상하다, 뭔가 어긋났다''는 뉘앙스야. 완전히 상했다기보다 ''어딘가 미묘하게 틀어졌다''는 느낌이라 하윤이 느낀 변화랑 딱 맞아. out, down, over는 taste와 이렇게 안 붙어. (CEFR B2)', '두 글자 짧은 단어, 우유가 상했을 때 "The milk is ___"라고 하지', '[]'),
(9, 2, 481, 'JA', '3年間ずっと同じお弁当だったので、もう______しまった。(3년 내내 같은 도시락이라 이제 완전히 질려버렸다)', '["焦って(あせって)","諦めて(あきらめて)","慣れて(なれて)","飽きて(あきて)"]', '飽きて(あきて)', '''飽きる(あきる)''는 같은 게 반복돼서 질리다, 싫증나다라는 뜻이야. 하윤이가 3년째 김밥에 지겨워하는 딱 그 감정이지. 慣れる는 ''익숙해지다'', 諦める는 ''포기하다'', 焦る는 ''조급해하다''라서 여기선 안 맞아. (JLPT N3)', '''飽''는 먹을 식(食) 옆에 쌀 포(包) — 배가 가득 차도록 먹어서 더는 못 먹겠는 상태', '[]'),
(9, 2, 481, 'ZH', '三年来，妈妈______每天凌晨给她做紫菜包饭，一天也没落下。(3년 동안 엄마는 하루도 빠짐없이 새벽에 김밥을 쌌다)', '["支持(zhīchí)","继续(jìxù)","坚持(jiānchí)","保持(bǎochí)"]', '坚持(jiānchí)', '''坚持 + 동사''는 힘들어도 포기하지 않고 꾸준히 ~하다라는 뜻의 고정 배합이야. 3년간 하루도 빠짐없이 김밥을 싼 엄마한테 딱 맞는 표현이지. 保持는 ''(상태를) 유지하다''(保持安静), 支持는 ''지지하다'', 继续는 ''중단했다가 이어서 하다''라 뉘앙스가 달라. (HSK 4급)', 'jiān으로 시작하는 2글자, ''힘들어도 포기 않고 계속하다''', '[]'),
(9, 3, 481, 'EN', '''하루도 빠짐없이''\n\nFor three years, Mom rolled kimbap at dawn ______ ______.\n(뜻: 단 한 번도 거르지 않고, 어김없이)', '[]', 'without fail', '''without fail''은 ''어김없이, 하루도 빠짐없이''라는 뜻으로, 오랫동안 반복된 습관이나 약속을 강조할 때 쓰는 표현이야. 3년 동안 새벽마다 김밥을 싼 엄마의 성실함을 딱 담아내는 말이지. ''day in and day out''도 ''날마다 지겹도록 계속''이라는 비슷한 뉘앙스로 쓸 수 있어. 반면 ''always''나 ''often''은 이런 ''단 한 번의 예외도 없었다''는 무게를 못 살려. (CEFR B2)', 'w_______ f___ (2단어) — ''실패(fail)'' 없이 = 빠짐없이', '["without fail","without failing","without exception","without missing a day","without a single miss","day in and day out","day in, day out","every single day"]'),
(9, 3, 481, 'JA', '''음식이 상하다''를 뜻하는 동사를 넣어봐.\n\n母はいつも「のり巻きが一番______にくいから」と言っていた。\n(뜻: 김밥이 제일 안 상하니까)', '[]', '傷み', '''傷む(いたむ)''는 음식이 상하거나 물건이 손상된다는 뜻이야. 뒤에 ''～にくい''가 붙으면 동사를 ます형(傷み)으로 바꿔서 ''傷みにくい = 잘 상하지 않는다''가 돼. 비슷한 ''腐る(くさる)''는 이미 완전히 썩어버린 상태를 말해서 뉘앙스가 더 강해. 엄마가 3년 동안 김밥만 싼 이유를 설명하는 딱 그 단어야. (JLPT N2)', 'い＋2글자(총 3글자). 한자 ''傷''은 사람(亻)이 상처 입은 모양 — 음식이 ''상처 입는'' 것도 같은 글자를 써', '["傷み","いたみ","傷む","いたむ","腐り","くさり"]'),
(9, 3, 481, 'ZH', '''어떤 일이 있어도 중단하지 않고, 하루도 빠짐없이''\n\n三年来，妈妈______，每天凌晨都起来卷紫菜包饭。\n(뜻: 3년 동안 엄마는 비바람에도 아랑곳없이 매일 새벽에 김밥을 쌌다)', '[]', '风雨无阻', '''风雨无阻(fēngyǔ wúzǔ)''는 비바람도 막지 못한다, 즉 어떤 상황에서도 멈추지 않고 계속한다는 뜻의 성어야. 3년 동안 하루도 빠짐없이 새벽에 김밥을 싼 엄마의 한결같음에 딱 맞는 표현이지. 비슷한 ''日复一日(rì fù yī rì)''는 그냥 ''하루하루 반복되다''라는 단조로움에 가깝고, ''坚持不懈(jiānchí bù xiè)''는 목표를 향해 꾸준히 노력한다는 뉘앙스라 ''어떤 방해에도 중단 없이''라는 느낌은 风雨无阻가 가장 강해. (HSK 6급)', '날씨(风雨)를 이기는 4글자 성어 — ''비바람도 막지 못한다''', '["风雨无阻","fēngyǔ wúzǔ","fengyu wuzu","fēng yǔ wú zǔ","feng yu wu zu","fēngyǔwúzǔ","fengyuwuzu"]'),
(9, 1, 493, 'EN', '김밥 때문에 짜증이 확 올라온 하윤의 기분을 나타내는 단어로 알맞은 것은?', '["ashamed","annoyed","amazed","amused"]', 'annoyed', '''annoyed''는 뭔가 거슬리고 짜증날 때 쓰는 형용사야. amazed는 놀란, ashamed는 부끄러운, amused는 재미있어하는 감정이라 여기엔 안 맞아. (CEFR A2)', 'a로 시작, 동사 annoy에서 온 형용사', '[]'),
(9, 1, 493, 'JA', '교문 앞에 엄마가 ''서 있었다''고 할 때, ''서다''에 해당하는 일본어 동사는?', '["座る(すわる)","立つ(たつ)","走る(はしる)","歩く(あるく)"]', '立つ(たつ)', '''立つ(たつ)''는 ''서다''라는 뜻이야. 교문 앞에 엄마가 서 있는 장면은 「校門の前に母が立っていた」처럼 말해. 座る(すわる)는 앉다, 歩く(あるく)는 걷다, 走る(はしる)는 달리다야. (JLPT N5)', '''立''는 사람이 땅(一) 위에 두 발로 버티고 선 모습을 본뜬 한자야', '[]'),
(9, 1, 493, 'ZH', '하윤이 엄마 말을 다 듣지 않고 전화를 끊어 버렸어. 다음 중 ''전화를 끊다''에 해당하는 중국어 표현은?', '["挂电话(guà diànhuà)","回电话(huí diànhuà)","接电话(jiē diànhuà)","打电话(dǎ diànhuà)"]', '挂电话(guà diànhuà)', '''挂(guà)''는 원래 ''걸다''라는 뜻인데, 전화기를 제자리에 ''걸어 놓는다''는 데서 ''挂电话(guà diànhuà) = 전화를 끊다''가 됐어. 接电话는 전화를 받다, 打电话는 전화를 걸다, 回电话는 답신 전화를 하다는 뜻이라 상황에 안 맞아. (HSK 4급)', 'guà로 시작 — ''벽에 걸다''라는 뜻도 있는 글자야', '[]'),
(9, 2, 493, 'EN', '''짜증, 신경질'' = i_________\n\nA sudden wave of ______ rose in her chest as she opened the lunchbox.\n(뜻: 도시락을 열자마자 갑자기 짜증이 확 치밀어 올랐다)', '[]', 'irritation', '''irritation''은 화(anger)보다는 약하지만, 순간적으로 확 올라오는 짜증·신경질을 딱 잡아주는 단어야. ''a wave of irritation''처럼 wave랑 자주 붙어 다니면서 감정이 훅 밀려오는 느낌을 표현해. 비슷한 말로 annoyance도 있지만, 여기선 i로 시작하는 irritation이 정답. (CEFR B2)', '동사 irritate(짜증나게 하다)의 명사형, i로 시작하고 -tion으로 끝나', '["irritation","Irritation","irritation."]'),
(9, 2, 493, 'JA', '''화가 치밀다, 짜증이 나다''\n\nお弁当を見た瞬間、急に______が立った。\n(도시락을 본 순간, 갑자기 화가 치밀었다)', '[]', '腹', '''腹が立つ(はらがたつ)''는 직역하면 ''배가 선다''지만 실제로는 ''화가 치밀다, 열받다''라는 뜻의 관용표현이야. 하윤이가 김밥을 보고 확 짜증이 올라온 그 순간에 딱 맞는 말이지. 비슷한 ''怒る(おこる)''가 화내는 행동을 말한다면, ''腹が立つ''는 속에서 감정이 확 솟아오르는 느낌이야. 참고로 화를 억누를 땐 ''腹を立てない''처럼 쓰기도 해. (JLPT N3)', 'は＋1글자 / 몸을 뜻하는 부수(月)가 붙은, ''배''를 가리키는 한자야', '["腹","はら","腹が","はらが"]'),
(9, 2, 493, 'ZH', '''짜증이 나다, 참을성이 없어지다''\n\n她听着听着有点______，直接挂了电话。\n(뜻: 듣다가 짜증이 나서 그냥 전화를 끊어버렸다)', '[]', '不耐烦', '''不耐烦(bùnàifán)''은 ''짜증이 나다, 귀찮아서 못 참겠다''는 뉘앙스야. 엄마 말에 확 짜증이 올라와 그냥 끊어버린 하윤의 감정에 딱 맞는 단어지. 참고로 전화를 끊는 건 ''挂电话(guà diànhuà)''라고 해. (HSK 5급)', 'bù + nài + fán (3글자) — ''耐心(인내심)''이 사라진 상태', '["不耐烦","bùnàifán","bunaifan","bú nài fán","bù nài fán","bu nai fan"]'),
(9, 3, 493, 'EN', '야자가 있는 날인데 엄마가 교문 앞에 서 있고, 하윤이 하지도 않은 말을 했다고 한다. ''뭔가 앞뒤가 맞지 않았다''를 이 맥락에서 가장 자연스럽게 표현한 것은?', '["Something didn''t go down well.","Something didn''t come across.","Something didn''t add up.","Something didn''t ring a bell."]', 'Something didn''t add up.', '''not add up''은 상황의 조각들이 서로 맞지 않아 이상하다, 앞뒤가 안 맞는다는 뜻의 관용표현이야. 엄마의 말과 실제 사실이 어긋나는 이 장면에 딱 맞지. ''ring a bell''은 어디서 들어본 듯 낯익다, ''come across''는 (인상이) 전달되다, ''go down well''은 반응이 좋다는 뜻이라 여기선 어색해. (CEFR C1)', '숫자를 더해도(add) 답이 안 맞을 때 쓰는 그 표현', '[]'),
(9, 3, 493, 'JA', '엄마가 "너 오늘 일찍 끝난다며"라고 했지만, 하윤은 그런 말을 한 기억이 전혀 없는 상황이야. 이럴 때 가장 자연스러운 일본어 관용표현은?', '["身に覚えがない","気が気でない","目に余る","口が滑る"]', '身に覚えがない', '''身(み)に覚(おぼ)えがない''는 ''그런 일을 한 기억이 전혀 없다, 전혀 짚이는 데가 없다''는 뜻이야. 하윤이 그런 말을 한 적이 없다고 느끼는 장면에 딱 맞아. ''気が気でない''는 걱정돼서 안절부절못하다, ''目に余る''는 도가 지나쳐 눈뜨고 볼 수 없다, ''口が滑る''는 무심코 말실수를 하다라는 뜻이라 맥락에 안 맞아. (JLPT N1)', '자기 자신(身)에게 그런 ''기억(覚え)''이 남아 있지 않다는 뜻의 신체 관련 관용구', '[]'),
(9, 3, 493, 'ZH', '야자가 있는 날인데 엄마가 장바구니를 든 채 교문 앞에 서서, 하윤이 한 적도 없는 말을 했다고 한다. 이 ''영문을 알 수 없는, 어리둥절한'' 상황을 나타내는 성어로 가장 적절한 것은?', '["理所当然(lǐ suǒ dāng rán)","兴高采烈(xìng gāo cǎi liè)","莫名其妙(mò míng qí miào)","一目了然(yī mù liǎo rán)"]', '莫名其妙(mò míng qí miào)', '''莫名其妙''는 영문을 알 수 없다, 까닭 없이 이상하다는 뜻이야. 하지도 않은 말을 엄마가 했다고 하니 딱 이 느낌이지. ''理所当然''은 당연하다, ''一目了然''은 한눈에 훤히 보인다, ''兴高采烈''은 신이 나서 들뜬 모습이라 맥락에 안 맞아. (HSK 6급)', '莫(mò)로 시작하는 4글자 성어 — ''이름 붙일 수 없을 만큼 이상하다''', '[]'),
(9, 1, 505, 'EN', '엄마가 오늘이 무슨 요일인지 헷갈려 했어. ''헷갈리다, 혼동하다''를 뜻하는 영어 단어는?', '["connect","confuse","compare","consider"]', 'confuse', '''confuse''는 두 가지를 헷갈리거나 혼동하다라는 뜻이야. ''She confused Tuesday with Wednesday.''처럼 쓰고, 사람이 헷갈릴 땐 ''I''m confused.''라고 해. (CEFR B1)', 'con-으로 시작하는 7글자 동사, 머릿속이 뒤엉킨 느낌', '[]'),
(9, 1, 505, 'JA', '도시락 가방이 평소보다 ''무거웠다''고 할 때 쓰는 일본어 형용사는?', '["重い(おもい)","広い(ひろい)","軽い(かるい)","長い(ながい)"]', '重い(おもい)', '''重い(おもい)''는 무겁다는 뜻이야. 김밥이 여섯 줄이나 들어 있어서 가방이 평소보다 무거웠던 거지. 반대말은 ''軽い(かるい/가볍다)''야. (JLPT N5)', '''重''는 물건을 겹겹이 쌓아 올려 놓은 모습에서 온 한자야', '[]'),
(9, 1, 505, 'ZH', '엄마가 대답하기 전에 잠깐 멈칫하며 머뭇거렸어. 이런 ''망설이다, 머뭇거리다''에 해당하는 중국어 표현은?', '["犹豫(yóuyù)","拒绝(jùjué)","后悔(hòuhuǐ)","假装(jiǎzhuāng)"]', '犹豫(yóuyù)', '''犹豫(yóuyù)''는 바로 대답하거나 결정하지 못하고 망설이는 걸 뜻해. 엄마가 요일을 듣고 잠깐 멈칫한 그 순간에 딱 맞는 단어야. 后悔는 후회하다, 拒绝는 거절하다, 假装은 ~인 척하다라는 뜻이라 상황이 달라. (HSK 4급)', 'yóu로 시작하는 2글자, 결정 못 하고 머뭇거릴 때 쓰는 말', '[]'),
(9, 2, 505, 'EN', 'Mom smiled and said she had ______ the days of the week.', '["mixed up","put up","made up","taken up"]', 'mixed up', '''mix up''은 두 가지를 서로 헷갈리거나 혼동하는 걸 말해. 요일을 착각한 엄마 상황에 딱 맞는 표현이야. ''make up''은 지어내다, ''take up''은 시작하다, ''put up''은 걸어두다라서 여기선 어색해. (CEFR B1)', '''섞다''라는 동사 + up, 두 단어짜리 구동사', '[]'),
(9, 2, 505, 'JA', 'エプロンのポケットが何かで______いた。(앞치마 주머니가 뭔가로 불룩했다)', '["破れて(やぶれて)","縮んで(ちぢんで)","膨らんで(ふくらんで)","曲がって(まがって)"]', '膨らんで(ふくらんで)', '''膨らむ(ふくらむ)''는 속에 뭔가 들어차서 불룩하게 부푼다는 뜻이야. 주머니가 볼록한 상태를 말할 때 딱 쓰는 표현이지. 縮む(줄어들다), 破れる(찢어지다), 曲がる(휘다)랑 헷갈리지 않게 주의! (JLPT N2)', '''膨''은 몸을 뜻하는 月(육달월) 옆에 크게 부풀어 오른 모양이 붙은 한자', '[]'),
(9, 2, 505, 'ZH', '妈妈笑着说："啊，对，妈妈把星期几______了。"（엄마가 요일을 헷갈렸다）', '["弄坏(nònghuài)","弄脏(nòngzāng)","弄错(nòngcuò)","弄丢(nòngdiū)"]', '弄错(nòngcuò)', '''弄错(nòngcuò)''는 ''잘못 알다, 착각하다, 헷갈리다''라는 뜻의 고정 배합이야. 把…弄错了 형태로 자주 써. 弄丢(잃어버리다), 弄脏(더럽히다), 弄坏(망가뜨리다)와 헷갈리지 않게 구별해두자. 엄마가 요일을 헷갈린 장면에 딱 맞는 표현이야. (HSK 4급)', '''弄(nòng)'' 뒤에 ''틀릴 错''가 붙으면? 잘못 알다·착각하다', '[]'),
(9, 3, 505, 'EN', '''그 웃음이 이상하게 오래 남았다'' — 사라지지 않고 마음에 계속 머무는 느낌\n\nThat smile ______ in my mind far longer than it should have.\n(뜻: 사라지지 않고 오래 머물다)', '[]', 'lingered', '''linger''는 사라져야 할 것이 사라지지 않고 계속 머무는 걸 뜻해. 냄새, 여운, 기억, 감정처럼 ''희미하게 남아 맴도는'' 것에 딱 맞는 단어야. 그냥 ''remained''나 ''stayed''보다 훨씬 문학적이고, 하윤이가 엄마 웃음에서 느낀 설명 못 할 찜찜함을 잘 담아내지. 참고로 ''lasted''는 단순히 지속 시간이 길다는 사실만 말하는 거라 이런 여운의 뉘앙스는 없어. (CEFR B2)', 'l______ed (향수 냄새나 여운이 ''가시지 않고 남을'' 때 쓰는 그 단어)', '["lingered","linger","lingered on","kept lingering","stayed","stayed with me"]'),
(9, 3, 505, 'JA', '''주머니가 불룩하게 부풀어 있었다''\n\n椅子にかかった母のエプロン。ポケットが______いた。\n(뜻: 불룩하게 부풀어 있었다)', '[]', 'ふくらんで', '''膨らむ(ふくらむ)''는 안에 뭔가 들어차서 불룩하게 부풀어 오르는 걸 말해. 주머니에 수첩이 들어 있어 툭 튀어나온 상태엔 딱 이 표현이야. 비슷한 ''太る''는 사람이 살찌는 것, ''腫れる(はれる)''는 몸이 붓는 것이라 여기선 안 맞아. (JLPT N2)', 'ふ＋4글자 / ''膨''은 살(月)이 부풀어 오르는 모습', '["ふくらんで","膨らんで","ふくらんでいた","膨らんでいた","ふくらんでて","膨らんでて"]'),
(9, 3, 505, 'ZH', '''마음이 뒤숭숭하고 안정되지 않다''\n\n那天以后，河允一直______，总觉得妈妈有点不对劲。\n(뜻: 그날 이후 하윤은 계속 마음이 불안했고, 엄마가 어딘가 이상하다고 느꼈다)', '[]', '心神不宁(xīn shén bù níng)', '''心神不宁(xīn shén bù níng)''은 마음과 정신이 안정되지 못해 뒤숭숭하고 불안한 상태를 말해. 엄마의 어색한 웃음이 계속 마음에 걸려서 친구들처럼 웃지 못하는 하윤의 상태에 딱 맞는 표현이야. 비슷한 ''紧张(jǐnzhāng)''은 눈앞의 일에 대한 순간적인 긴장이고, ''忐忑不安(tǎntè bù ān)''은 뭔가를 앞두고 조마조마한 느낌이라면, ''心神不宁''은 이유를 꼭 집을 수 없는 불안이 계속 마음에 머무는 뉘앙스야. (HSK 6급)', '心으로 시작하는 4글자 성어, 마지막 글자는 ''편안할 宁''', '["心神不宁","心神不宁(xīn shén bù níng)","xīn shén bù níng","xinshen buning","xīnshén bùníng","xin shen bu ning","心神不安"]'),
(9, 1, 517, 'EN', '수첩 마지막 장에서 병원 진료 카드를 발견한 순간처럼, ''(우연히) 발견하다, 알아차리다''를 뜻하는 단어는?', '["describe","discover","decide","deliver"]', 'discover', '''discover''는 몰랐던 것을 발견하거나 알게 되다라는 뜻이야. 하윤이가 수첩 사이에 끼워진 진료 카드를 발견한 장면에 딱 맞는 단어지. (CEFR A2)', 'd로 시작, ''커버를 벗기다''에서 온 단어', '[]'),
(9, 1, 517, 'JA', '하윤이 수첩과 진료 카드를 보고 속으로 내뱉은 ''거짓말''에 해당하는 일본어 단어는?', '["夢(ゆめ)","嘘(うそ)","声(こえ)","話(はなし)"]', '嘘(うそ)', '''嘘(うそ)''는 ''거짓말''이라는 뜻이야. 다음 예약이 비어 있는 진료 카드를 보고 아빠의 말이 거짓말이었다는 걸 깨닫는 장면이지. (JLPT N4)', '''嘘''는 입(口)에서 나오는 텅 빈(虚) 말이라는 뜻이야', '[]'),
(9, 1, 517, 'ZH', '수첩 스무 장 넘게 똑같은 문장이 계속 쓰여 있었어. 이때 ''반복하다''를 뜻하는 중국어 표현으로 알맞은 것은?', '["重复(chóngfù)","增加(zēngjiā)","继续(jìxù)","改变(gǎibiàn)"]', '重复(chóngfù)', '''重复(chóngfù)''는 같은 말이나 행동을 되풀이한다는 뜻이야. 날짜만 바뀐 채 똑같은 문장이 스무 장 넘게 이어진 상황에 딱 맞는 단어지. 继续(jìxù)는 ''계속하다'', 增加(zēngjiā)는 ''증가하다'', 改变(gǎibiàn)은 ''바꾸다''라서 여기선 안 맞아. (HSK 4급)', 'chóng으로 시작하는 2글자, ''重''가 들어가', '[]'),
(9, 2, 517, 'EN', '''(사이에) 끼워 넣다, 밀어 넣다'' = t______\n\nA hospital appointment card was ______ between the last two pages of the notebook.\n(뜻: 진료 카드 한 장이 수첩 마지막 장 사이에 끼워져 있었다)', '[]', 'tucked', '''tuck A between B''는 무언가를 좁은 틈 사이에 끼워 넣거나 슬쩍 숨겨 두는 걸 말해. 수첩 마지막 장 사이에 진료 카드가 조용히 끼워져 있던 장면에 딱 맞는 표현이야. ''tuck away''로 쓰면 ''잘 넣어 두다, 숨겨 두다''가 돼. (CEFR B2)', 't로 시작, 6글자. 이불을 몸에 ''폭'' 여며 덮어줄 때도 쓰는 그 단어 🛏️', '["tucked","Tucked","tuck","was tucked"]'),
(9, 2, 517, 'JA', '''(사이에) 끼어 있다''\n\n手帳(てちょう)の最後(さいご)のページの間(あいだ)に、紙(かみ)が一枚(いちまい)______いた。\n(수첩 맨 마지막 장 사이에 종이 한 장이 끼워져 있었다)', '[]', '挟まって', '''挟まる(はさまる)''는 무언가 사이에 끼어 있다는 자동사야. 여기선 종이가 저절로 끼여 있는 상태라 ''挟まっていた''가 딱 맞아. 누가 끼워 넣는 동작을 말할 땐 타동사 ''挟む(はさむ)''를 써서 ''紙を挟む''처럼 쓰고, 수동으로 ''挟まれる''라고 해도 통해. (JLPT N2)', 'は＋4글자 (한자 ''挟''는 손(扌)으로 양쪽에서 끼우는 모양)', '["挟まって","はさまって","挟まれて","はさまれて"]'),
(9, 2, 517, 'ZH', '''거짓말하다''\n\n原来他一直在对我______，三个月前就去医院了。\n(뜻: 알고 보니 그는 계속 나에게 거짓말을 하고 있었다)', '[]', '撒谎(sāhuǎng)', '''撒谎(sāhuǎng)''은 ''거짓말하다''라는 뜻의 이합사야. 중간에 다른 말이 끼어들어 ''撒了一个谎(거짓말을 하나 했다)''처럼 쓸 수도 있어. 비슷한 말로 ''说谎(shuōhuǎng)''도 있어. 진료 카드를 숨기고 아무 일 없는 척했던 아빠의 모습에 딱 맞는 표현이지. (HSK 5급)', 'sā + huǎng (2글자, ''거짓 谎''이 들어가는 이합사)', '["撒谎","sāhuǎng","sahuang","sā huǎng","说谎","shuōhuǎng","shuohuang"]'),
(9, 3, 517, 'EN', '수첩 사이에서 신경과 진료 카드를 발견한 순간, 하윤이 지금까지의 모든 일이 무엇을 뜻했는지 서서히 깨닫게 돼. 이 상황을 가장 자연스럽게 표현한 문장은?', '["The truth slowly ran over her.","The truth slowly dawned on her.","The truth slowly wore on her.","The truth slowly grew on her."]', 'The truth slowly dawned on her.', '''dawn on someone''은 어떤 사실이 서서히 머릿속에 밝아오듯 이해되기 시작한다는 뜻이야. 똑같은 문장이 스무 장 넘게 반복되고, 글씨가 점점 흐트러지고, 예약 칸이 비어 있는 걸 보면서 하윤이 진실을 알아차리는 순간에 딱 맞아. ''grow on someone''은 점점 마음에 들게 되다, ''wear on someone''은 사람을 서서히 지치게 하다, ''run over''는 (차로) 치다/대충 훑어보다라는 뜻이라 이 맥락엔 안 맞아. (CEFR C1)', 'd____ on her — 새벽빛이 서서히 밝아오듯 깨달음이 스며드는 동사', '[]'),
(9, 3, 517, 'JA', '빈 예약 칸을 본 순간, 하윤이 충격으로 숨이 턱 멎는 듯한 반응을 나타내기에 가장 알맞은 표현은?', '["息をついた","息を切らした","息をのんだ","息が長かった"]', '息をのんだ', '''息をのむ(いきをのむ)''는 놀라움이나 충격으로 순간 숨이 멎는 걸 뜻해. 비어 있는 예약 칸을 본 하윤의 반응에 딱 맞지. ''息を切らす''는 헐떡이며 숨이 차는 것, ''息をつく''는 한숨 돌리며 안도하는 것, ''息が長い''는 오래 지속된다는 뜻이라 여기선 안 맞아. (JLPT N1)', '''呑''은 하늘(天) 아래 입(口)으로 꿀꺽 삼키는 모양 — 놀라서 ''숨(息)''을 삼켜 버리는 관용구', '[]'),
(9, 3, 517, 'ZH', '''(진실·병세 등을) 숨기다, 감추다''\n\n他一直______着自己的病情，不让女儿知道。\n(뜻: 그는 줄곧 자신의 병세를 숨기고 딸이 알지 못하게 했다)', '[]', '隐瞒', '''隐瞒(yǐnmán)''은 사실이나 진실을 일부러 감추고 알리지 않는다는 뜻이야. 비슷한 ''隐藏(yǐncáng)''은 물건이나 모습을 물리적으로 숨기는 쪽에 가깝고, ''掩饰(yǎnshì)''는 감정이나 실수를 겉으로 덮어 가리는 느낌이야. 아빠가 신경과 진료 사실을 딸에게 말하지 않고 수첩에 같은 문장만 반복해 적어둔 상황이라, 병세를 ''숨긴'' 隐瞒이 딱 맞아. (HSK 6급)', 'yǐn으로 시작하는 2글자 동사, 뒤 글자는 ''속일 만(瞒)''', '["隐瞒","yǐnmán","yinman","隐瞒了","yǐn mán","yin man"]'),
(9, 1, 533, 'EN', '하윤은 엄마의 김밥 레시피를 이제 자기가 기억하기로 마음먹었어요. 다음 중 ''~하기로 결정하다, 마음먹다''를 뜻하는 단어는?', '["decide","deserve","divide","deliver"]', 'decide', '''decide''는 ''결정하다, 마음먹다''라는 뜻이야. She decided to remember it herself. 처럼 ''decide to + 동사원형''으로 자주 써. 하윤이가 엄마의 김밥을 이제 자기가 기억하기로 마음먹은 마지막 장면에 딱 맞는 단어지. (CEFR A2)', 'd로 시작하는 6글자, 명사형은 decision', '[]'),
(9, 1, 533, 'JA', '하윤이 새 수첩에 엄마의 김밥 비법을 적으며 ''이건 내가 기억하겠다''고 마음먹었어. 다음 중 ''기억하다, 외우다''에 해당하는 일본어는?', '["忘れる(わすれる)","覚える(おぼえる)","教える(おしえる)","調べる(しらべる)"]', '覚える(おぼえる)', '''覚える(おぼえる)''는 기억하다, 외우다라는 뜻이야. 하윤이가 엄마의 레시피를 자기가 기억하기로 한 마지막 장면에 딱 맞는 단어지. 참고로 忘れる는 잊다, 教える는 가르치다, 調べる는 조사하다라는 뜻이야. (JLPT N4)', '이 한자 아래쪽에는 ''보다(見)''가 들어 있어. 눈으로 보고 머리에 담아 깨닫는다는 뜻이야', '[]'),
(9, 1, 533, 'ZH', '하윤이 수첩에 적으며 ''(잊지 않고) 기억해 두다''라고 다짐했을 때, 가장 알맞은 중국어 표현은?', '["记住(jìzhù)","认识(rènshi)","忘记(wàngjì)","发现(fāxiàn)"]', '记住(jìzhù)', '''记住(jìzhù)''는 단순히 기억난다가 아니라 ''잊지 않게 확실히 기억해 두다''라는 뉘앙스야. 엄마의 김밥 레시피를 이제 자기가 기억하겠다고 마음먹은 마지막 장면에 딱 맞는 표현이지. 참고로 忘记(wàngjì)는 ''잊다''로 정반대 뜻이야. (HSK 3급)', 'jì로 시작하고, 뒤에 ''확실히 ~해 두다''를 뜻하는 住가 붙어요', '[]'),
(9, 2, 533, 'EN', 'He wrote it down in his own notebook and decided to ______ it upon himself to remember his mom''s recipe.', '["carry","put","take","bring"]', 'take', '''take it upon oneself (to do something)''는 누가 시키지 않았는데도 스스로 책임지고 맡는다는 뜻이야. 하윤이 엄마의 레시피를 이제 자기가 기억하겠다고 마음먹은 마지막 장면에 딱 맞는 표현이지. put/bring/carry는 이 관용구에서는 쓰지 않아. (CEFR B2)', '책임을 ''가져가다'' — 가장 기본적인 동사, t로 시작', '[]'),
(9, 2, 533, 'JA', '母のキンパの味は、これから自分が______ことにした。(엄마 김밥의 맛은 이제 자기가 이어받기로 했다)', '["受け継ぐ(うけつぐ)","受け入れる(うけいれる)","受け取る(うけとる)","引き受ける(ひきうける)"]', '受け継ぐ(うけつぐ)', '''受け継ぐ(うけつぐ)''는 앞사람의 것을 물려받아 이어간다는 뜻이야. 엄마의 손맛이나 전통처럼 ''대를 이어 물려받는'' 상황에 딱 맞지. 受け取る는 물건을 ''받다'', 受け入れる는 의견 등을 ''받아들이다'', 引き受ける는 일을 ''떠맡다''라서 여기선 어색해. 하윤이가 수첩에 적으며 엄마의 김밥을 자기 기억으로 이어가기로 한 마지막 장면에 어울리는 표현이야. (JLPT N2)', '''継''는 실(糸)을 이어 붙이듯 끊긴 뒤를 계속 잇는다는 뜻이야', '[]'),
(9, 2, 533, 'ZH', '她在本子第一页写下妈妈的做法，下定______，这件事以后由自己记住。(마음을 굳게 먹고, 이건 앞으로 자기가 기억하기로 했다)', '["耐心(nàixīn)","关心(guānxīn)","决心(juéxīn)","信心(xìnxīn)"]', '决心(juéxīn)', '''下定决心(xiàdìng juéxīn)''은 ''굳게 결심하다''라는 고정 배합이야. 엄마의 김밥 레시피를 이제부터 자기가 기억하겠다고 마음먹는 하윤이의 다짐에 딱 맞는 표현이지. 信心(자신감), 耐心(인내심), 关心(관심)은 ''下定''과 함께 쓰지 않아. (HSK 5급)', '''心''으로 끝나는 2글자, jué로 시작 — 마음을 굳게 정하는 것', '[]'),
(9, 3, 533, 'EN', '''이건 (누가 시키지 않았지만) 자기가 기억하기로 했다''\n\nShe ______ ______ ______ herself to remember this.\n(뜻: 스스로 그 책임을 떠맡다 — 3단어)', '[]', 'took it upon', '''take it upon oneself (to do something)''는 아무도 부탁하지 않았는데 스스로 그 일을/책임을 떠맡는다는 뜻이야. 하윤이 수첩 얘기를 꺼내지 않고 조용히 똑같은 수첩을 사서 직접 적어두는 장면 — 엄마의 기억을 이제 자기가 이어받겠다는 조용한 결심이라 딱 맞는 표현이지. 비슷하게 ''took it on''도 쓸 수 있지만, ''take it upon oneself''가 ''자발적으로 짊어진다''는 뉘앙스를 가장 잘 살려줘. (CEFR C1)', 't___ i_ u___ : 그 짐을 ''자기 위에'' 얹는 느낌 (동사는 과거형)', '["took it upon","take it upon","took it upon herself","take it upon herself","took it on","took this upon"]'),
(9, 3, 533, 'JA', '''단순히 외우는 게 아니라, 잊지 않도록 마음에 깊이 새기다''\n\n母の味を、これからは自分が心に______。\n(뜻: (마음에) 새겼다)', '[]', '刻んだ', '''心に刻む(こころにきざむ)''는 칼로 새기듯 마음속에 깊이 새겨 절대 잊지 않는다는 뜻의 고급 관용표현이야. 그냥 ''覚える(외우다)''가 정보를 기억하는 중립적인 말이라면, ''刻む''는 소중한 것을 평생 간직하겠다는 각오가 담겨 있어. 엄마의 수첩 대신 자기 수첩에 엄마 김밥 레시피를 적으며 ''이건 내가 기억하기로 했다''고 다짐하는 마지막 장면에 딱 맞는 표현이지. (JLPT N1)', 'き＋3글자 / 칼로 파서 자국을 남기듯 마음에 남기는 동사의 과거형', '["刻んだ","きざんだ","刻む","きざむ","心に刻んだ","こころにきざんだ"]'),
(9, 3, 533, 'ZH', '''(잊지 않도록) 마음 깊이 새겨 기억하다''\n\n这一次，轮到他把妈妈的味道______在心里。\n(뜻: 이번엔 그가 엄마의 맛을 마음에 새기기로 했다)', '[]', '铭记(míngjì)', '''铭记(míngjì)''는 비석에 글자를 새기듯 마음속 깊이 새겨 잊지 않는다는 뜻이야. 그냥 ''记住(기억하다)''보다 훨씬 무겁고 진지한 느낌이라, 하윤이 엄마의 수첩 대신 자기 수첩에 레시피를 적으며 ''이건 내가 기억하겠다''고 다짐하는 마지막 장면에 딱 맞아. 비슷한 ''牢记(láojì)''는 ''단단히 기억하다''로 의지·당부의 뉘앙스가 강하고, ''刻骨铭心(kègǔ míngxīn)''은 뼈에 사무칠 만큼 잊을 수 없는 경험을 말할 때 써. (HSK 6급)', 'míng으로 시작하는 2글자, 금속·돌에 글자를 ''새기다(铭)''에서 온 말', '["铭记","míngjì","mingji","míng jì","铭记在心","铭记于心","牢记","láojì","laoji"]');
INSERT INTO _su_qmap (quiz_id, content_id, difficulty, break_no)
INSERT INTO quiz_content (quiz_id, lang_code, question, options, correct_answer, explanation, hint, acceptable_answers)
