-- =============================================
-- story-unlock-data.sql : 스토리 해금 content_id 7~9 (EN / JA / ZH)
-- =============================================
-- * 서버(data.sql)가 아니라 mysql CLI 에서 직접 실행하는 스크립트 (sql.init.mode=never 유지)
-- * 실행 전 세션을 utf8mb4 로 맞출 것:
--     mysql -h <host> -u admin -p --default-character-set=utf8mb4 qring_db
--     source C:/경로/story-unlock-data.sql;
-- * 삭제 없이 기존 ID 그대로 내용만 덮어쓴다 -> story_progress 등 참조 데이터는 유지된다
-- * 맨 아래 확인 쿼리를 보고 이상 없으면 COMMIT; / 이상하면 ROLLBACK;
--   (COMMIT/ROLLBACK 하기 전에 터미널을 닫으면 자동 ROLLBACK)
-- * script_id 매핑 (기존 DB 기준 가정)
--     content 7 (6호차 4번 좌석) : script_id 361~426 (66개)
--     content 8 (초록색 문제만 한 달째 안 뜯겨 있었음) : script_id 427~469 (43개)
--     content 9 (여섯 줄) : script_id 470~533 (64개)

SET NAMES utf8mb4;

-- ---------- 임시 테이블 (세션 종료 시 자동 삭제) ----------
DROP TEMPORARY TABLE IF EXISTS _su_script;
DROP TEMPORARY TABLE IF EXISTS _su_quiz;
DROP TEMPORARY TABLE IF EXISTS _su_content;
DROP TEMPORARY TABLE IF EXISTS _su_qmap;

CREATE TEMPORARY TABLE _su_script (
    script_id BIGINT NOT NULL PRIMARY KEY,
    content_id BIGINT NOT NULL,
    sequence_num INT NOT NULL,
    script_content TEXT NOT NULL
);
CREATE TEMPORARY TABLE _su_quiz (
    content_id BIGINT NOT NULL,
    break_no INT NOT NULL,
    difficulty INT NOT NULL,
    script_id BIGINT NOT NULL,
    quiz_type VARCHAR(200) NOT NULL,
    PRIMARY KEY (content_id, break_no, difficulty)
);
CREATE TEMPORARY TABLE _su_content (
    content_id BIGINT NOT NULL,
    difficulty INT NOT NULL,
    script_id BIGINT NOT NULL,
    lang_code VARCHAR(5) NOT NULL,
    question TEXT NOT NULL,
    options JSON NOT NULL,
    correct_answer TEXT NOT NULL,
    explanation TEXT NOT NULL,
    hint TEXT NOT NULL,
    acceptable_answers JSON NOT NULL,
    PRIMARY KEY (content_id, difficulty, script_id, lang_code)
);
CREATE TEMPORARY TABLE _su_qmap (
    quiz_id BIGINT NOT NULL PRIMARY KEY,
    content_id BIGINT NOT NULL,
    difficulty INT NOT NULL,
    break_no INT NOT NULL
);

-- ---------- 1. 새 데이터 적재 (임시 테이블) ----------
-- script: content 7 (6호차 4번 좌석) 66개

-- script: content 8 (초록색 문제만 한 달째 안 뜯겨 있었음) 43개

-- script: content 9 (여섯 줄) 64개

-- quiz_detail 새 매핑: 스토리마다 퀴즈 구간 5개 x 난이도 3개 = 15개

-- quiz_content: content 7 (6호차 4번 좌석) 45개

-- quiz_content: content 8 (초록색 문제만 한 달째 안 뜯겨 있었음) 45개

-- quiz_content: content 9 (여섯 줄) 45개

-- ---------- 2. 실제 테이블 갱신 (트랜잭션) ----------
-- * lang_code 비교에 COLLATE 를 명시한 이유: quiz_content 는 utf8mb4_unicode_ci, 임시 테이블은 DB 기본(utf8mb4_0900_ai_ci)이라
--   그냥 비교하면 ERROR 1267(Illegal mix of collations) 이 난다
START TRANSACTION;

-- 2-1. content 제목
UPDATE content SET title = '6호차 4번 좌석' WHERE content_id = 7;
UPDATE content SET title = '초록색 문제만 한 달째 안 뜯겨 있었음' WHERE content_id = 8;
UPDATE content SET title = '여섯 줄' WHERE content_id = 9;

-- 2-2. script (script_id + content_id 가 모두 맞는 행만 갱신)
UPDATE script s
JOIN _su_script t ON t.script_id = s.script_id AND t.content_id = s.content_id
SET s.script_content = t.script_content, s.sequence_num = t.sequence_num;

-- 2-3. quiz_detail: (content_id, difficulty, 스토리 안 순서) 로 기존 행을 찾아 script_id / quiz_type 갱신
SELECT quiz_id, content_id, difficulty,
       ROW_NUMBER() OVER (PARTITION BY content_id, difficulty ORDER BY script_id, quiz_id)
FROM quiz_detail
WHERE content_id IN (7, 8, 9);

UPDATE quiz_detail d
JOIN _su_qmap m ON m.quiz_id = d.quiz_id
JOIN _su_quiz n ON n.content_id = m.content_id AND n.difficulty = m.difficulty AND n.break_no = m.break_no
SET d.script_id = n.script_id, d.quiz_type = n.quiz_type;

-- 2-4. quiz_content: 기존 행 갱신 (quiz_id + lang_code)
UPDATE quiz_content c
JOIN quiz_detail d ON d.quiz_id = c.quiz_id
JOIN _su_content t ON t.content_id = d.content_id AND t.difficulty = d.difficulty AND t.script_id = d.script_id
     AND t.lang_code COLLATE utf8mb4_unicode_ci = c.lang_code COLLATE utf8mb4_unicode_ci
SET c.question = t.question, c.options = t.options, c.correct_answer = t.correct_answer,
    c.explanation = t.explanation, c.hint = t.hint, c.acceptable_answers = t.acceptable_answers;

-- 2-5. quiz_content: 없는 (quiz_id, 언어) 만 새로 추가
SELECT d.quiz_id, t.lang_code, t.question, t.options, t.correct_answer, t.explanation, t.hint, t.acceptable_answers
FROM _su_content t
JOIN quiz_detail d ON d.content_id = t.content_id AND d.difficulty = t.difficulty AND d.script_id = t.script_id
WHERE NOT EXISTS (SELECT 1 FROM quiz_content c WHERE c.quiz_id = d.quiz_id
                  AND c.lang_code COLLATE utf8mb4_unicode_ci = t.lang_code COLLATE utf8mb4_unicode_ci);

-- ---------- 3. 확인 (전부 기대값이 나와야 COMMIT) ----------
-- 3-1. script 개수  (기대: 7 = 66, 8 = 43, 9 = 64)
SELECT content_id, COUNT(*) AS scripts, MIN(script_id) AS min_id, MAX(script_id) AS max_id
FROM script WHERE content_id IN (7, 8, 9) GROUP BY content_id ORDER BY content_id;

-- 3-2. 새 내용과 안 맞는 script 수  (기대: 0)
SELECT COUNT(*) AS script_mismatch
FROM _su_script t
LEFT JOIN script s ON s.script_id = t.script_id AND s.content_id = t.content_id
     AND s.sequence_num = t.sequence_num AND BINARY s.script_content = BINARY t.script_content
WHERE s.script_id IS NULL;

-- 3-3. quiz_detail 개수  (기대: 스토리 7/8/9 x 난이도 1/2/3 = 전부 5)
SELECT content_id, difficulty, COUNT(*) AS n FROM quiz_detail
WHERE content_id IN (7, 8, 9) GROUP BY content_id, difficulty ORDER BY content_id, difficulty;

-- 3-4. 새 매핑과 안 맞는 quiz_detail 수  (기대: 0 / 0)
SELECT COUNT(*) AS detail_missing
FROM _su_quiz n
LEFT JOIN quiz_detail d ON d.content_id = n.content_id AND d.difficulty = n.difficulty
     AND d.script_id = n.script_id AND d.quiz_type = n.quiz_type
WHERE d.quiz_id IS NULL;
SELECT COUNT(*) AS detail_extra
FROM quiz_detail d
LEFT JOIN _su_quiz n ON n.content_id = d.content_id AND n.difficulty = d.difficulty AND n.script_id = d.script_id
WHERE d.content_id IN (7, 8, 9) AND n.content_id IS NULL;

-- 3-5. quiz_content 언어별 개수  (기대: EN / JA / ZH 각 45)
SELECT c.lang_code, COUNT(*) AS n FROM quiz_content c
JOIN quiz_detail d ON d.quiz_id = c.quiz_id WHERE d.content_id IN (7, 8, 9)
GROUP BY c.lang_code ORDER BY c.lang_code;

-- 3-6. 새 내용과 안 맞는 quiz_content 수  (기대: 0)
SELECT COUNT(*) AS content_mismatch
FROM _su_content t
JOIN quiz_detail d ON d.content_id = t.content_id AND d.difficulty = t.difficulty AND d.script_id = t.script_id
LEFT JOIN quiz_content c ON c.quiz_id = d.quiz_id
     AND c.lang_code COLLATE utf8mb4_unicode_ci = t.lang_code COLLATE utf8mb4_unicode_ci
     AND BINARY c.question = BINARY t.question AND BINARY c.correct_answer = BINARY t.correct_answer
     AND BINARY c.explanation = BINARY t.explanation AND BINARY c.hint = BINARY t.hint
     AND c.options = t.options AND c.acceptable_answers = t.acceptable_answers
WHERE c.quiz_content_id IS NULL;

-- 이상 없으면:  COMMIT;
-- 하나라도 다르면:  ROLLBACK;  (그대로 알려줘)
